// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Finansal piyasalar ve yatırım araçları (orta).
const ozEconomics11Orta = <(String, String, List<String>, String)>[
  ('Bir hisse 30 TL\'den işlem görüyor. Şirket, elinde 4 payı olan ortağa 1 yeni payı 20 TL\'ye alma hakkı veriyor. Rüçhan kullanıldıktan sonra beklenen teorik fiyat kaç TL\'dir?', '28', ['26,5', '25', '29'], 'Teorik fiyat = (4×30 + 1×20) / 5 = 140 / 5 = 28 TL. Yeni pay ucuz satıldığı için ortalama fiyat aşağı çeker.'),
  ('Halka arzda talep toplama sırasında şirketin yalnızca bir fiyat aralığı açıkladığı, nihai fiyatın gelen taleplere göre belirlendiği yönteme ne denir?', 'Talep toplama (book building) yöntemi', ['Sabit fiyatlı satış, fiyat aralığı verilmeden', 'Doğrudan borsada işlem başlatma', 'Hisse takası'], 'Book building yönteminde yatırımcıların hangi fiyatlardan ne kadar talep ettiği toplanır ve nihai halka arz fiyatı buna göre saptanır.'),
  ('Bir şirket hisselerini 2\'ye 1 oranında bölüyor (her 1 hisse 2 hisse oluyor). Bölünmeden önce hisse fiyatı 80 TL ve piyasa değeri 4 milyar TL ise bölünme sonrası teorik fiyat ve piyasa değeri nedir?', '40 TL ve 4 milyar TL', ['40 TL ve 2 milyar TL', '80 TL ve 8 milyar TL', '160 TL ve 4 milyar TL'], 'Bölünmede pay sayısı iki katına çıkar, fiyat yarıya iner; şirketin toplam değeri değişmez.'),
  ('Yıl boyunca kârın büyük bölümünü yeni yatırımlara ayıran hızlı büyüyen bir şirketin temettü politikası için hangisi en olasıdır?', 'Düşük temettü dağıtım oranı', ['Kârın tamamını temettü olarak dağıtmak', 'Hiç kâr elde etmeden temettü ödemek', 'Borçlanıp yüksek temettü vermek'], 'Büyüme aşamasındaki şirketler kârı yatırıma çevirmeyi yeğler; olgun ve nakit üreten şirketler daha yüksek temettü öder.'),
  ('Bir şirketin hisse fiyatı bedelsiz artırımın ardından yeni fiyata göre \'düzeltilmiş\' hesaplanır. Bu düzeltmenin temel amacı nedir?', 'Geçmiş fiyat grafiklerinin yapay düşüşler nedeniyle yanıltmamasını sağlamak', ['Şirketin vergisini azaltmak', 'Temettü verimini artırmak', 'Borsa komisyonunu sıfırlamak'], 'Bedelsizde fiyat teknik olarak düşer; düzeltme yapılmazsa grafik gerçek bir zarar varmış gibi görünür.'),
  ('Bir şirket 100 milyon TL olan sermayesini 150 milyon TL\'ye bedelsiz artırıyor. Her 100 paya kaç yeni pay verilir?', '50', ['150', '33', '100'], 'Artış oranı (150−100)/100 = yüzde 50\'dir; sahip olunan her 100 paya 50 bedelsiz pay verilir.'),
  ('F/K oranı 20, yıllık kâr büyümesi beklentisi yüzde 10 olan bir hissenin PEG oranı kaçtır?', '2', ['0,5', '200', '10'], 'PEG = F/K oranı / beklenen büyüme yüzdesi = 20 / 10 = 2\'dir; büyüme hesaba katıldığında hissenin pahalılığını gösterir.'),
  ('Fiyat/satış (F/S) oranının zarar eden büyüme şirketlerini değerlendirmede F/K\'ya göre bir avantajı nedir?', 'Zarar durumunda da hesaplanabilir ve anlamlı bir sayı verir', ['Kâr marjını gizler', 'Borçları hesaba katar', 'Yalnızca bankalarda kullanılabilir'], 'Net kâr negatifken F/K anlamsız çıkar; satış geliri ise hâlâ pozitif olduğundan F/S ile karşılaştırma yapılabilir.'),
  ('Piyasa değeri 900 milyon TL, net borcu 300 milyon TL olan bir şirketin kabaca işletme (firma) değeri kaç milyon TL\'dir?', '1.200', ['600', '900', '270.000'], 'Firma değeri = piyasa değeri + net borç = 900 + 300 = 1.200 milyon TL; şirketi tümüyle satın alan, borcu da üstlenir.'),
  ('Bir hissenin 20 günlük hareketli ortalaması, 50 günlük ortalamasını aşağıdan yukarıya doğru kesiyor. Teknik analiz yorumcuları buna ne ad verir ve nasıl yorumlar?', 'Altın kesişim; yükseliş sinyali', ['Ölüm kesişimi; düşüş sinyali', 'Temettü kesişimi; ödeme sinyali', 'Likidite kesişimi; işlem durdurma sinyali'], 'Kısa vadeli ortalamanın uzun vadeliyi yukarı kesmesi altın kesişim, aşağı kesmesi ölüm kesişimi diye adlandırılır.'),
  ('Bir hisse fiyatı uzun süredir 40-50 TL aralığında gidip gelirken yüksek hacimle 50 TL\'nin üzerine çıkıyor. Teknik analizcilerin yorumu nedir?', 'Direnç aşıldı; yükseliş eğiliminin başlama ihtimali', ['Fiyatın artık direnç bölgesine yeniden girdiği ve satış zamanı olduğu', 'Şirket borsadan çıkıyor', 'Fiyat mutlaka geri 40\'a dönecek'], 'Yüksek hacimle gelen yukarı kırılım, direncin aşıldığı ve alıcıların güçlendiği şeklinde yorumlanır; kesin kâr garantisi olmaz.'),
  ('Piyasa değeri ağırlıklı bir endekste iki şirketten A\'nın değeri 900 milyar, B\'ninki 100 milyar TL\'dir. Her ikisi de aynı gün yüzde 10 düşerse endeks yaklaşık yüzde kaç düşer?', '10', ['9,5', '9', '1'], 'Her ikisi de yüzde 10 düştüğü için ağırlıkları ne olursa olsun toplam değer de yüzde 10 azalır.'),
  ('Aynı koşullarda yalnızca A şirketi yüzde 10 düşer, B değişmezse piyasa değeri ağırlıklı endeksteki düşüş yaklaşık yüzde kaçtır? (A: 900 milyar, B: 100 milyar TL)', '9', ['10', '1', '5'], 'Düşüş = 900×0,10 / 1.000 = 0,09, yani yüzde 9\'dur; büyük şirket endeks üzerinde belirleyici olur.'),
  ('Borsa İstanbul\'da zarar eden, bilançosu kötüleşen ya da kotasyon koşullarını yerine getirmeyen şirketlerin işlem gördüğü ve yatırımcıyı uyarmak için ayrı tutulan piyasa hangisidir?', 'Yakın İzleme Pazarı', ['Yıldız Pazar', 'Altın Piyasası', 'Opsiyon Piyasası'], 'Yakın İzleme Pazarı, dikkat gerektiren şirketlerin payları için tasarlanmış ayrı bir işlem bölümüdür.'),
  ('Bir yatırımcı 100 payı 10 TL\'den, 300 payı 12 TL\'den alıyor. Hacim ağırlıklı ortalama fiyatı (VWAP) kaç TL\'dir?', '11,5', ['11', '11,75', '12,5'], 'Toplam tutar 100×10 + 300×12 = 4.600 TL; toplam pay 400 olduğundan ortalama 4.600 / 400 = 11,5 TL\'dir.'),
  ('6 Mayıs 2010\'da ABD hisse piyasalarında Dow Jones endeksinin dakikalar içinde yaklaşık bin puan düşüp büyük bölümünü hızla geri kazandığı olay hangi adla anılır?', 'Ani çöküş (flash crash)', ['Kara Pazartesi (1987\'deki tek günlük çöküş)', 'Kara Perşembe', 'Lale çılgınlığı'], '2010 flash crash\'inde otomatik satış emirleri ve likidite çekilmesi ani bir fiyat düşüşü yarattı; piyasa kısa sürede toparlandı.'),
  ('Ekranda 9,80 TL alış, 9,90 TL satış fiyatı görünen bir hissede \'piyasa emri\' ile alım yapan kişi büyük olasılıkla hangi fiyattan gerçekleşme bekler?', '9,90 TL civarı', ['9,80 TL civarı', '9,00 TL civarı', '10,50 TL civarı'], 'Piyasa emri anında karşılanır ve alıcı en iyi satış fiyatını öder; makas bu yüzden yatırımcı için bir işlem maliyetidir.'),
  ('Büyük bir hisse paketinin tek seferde satışını piyasada fiyat çökmeden yapabilmek için profesyoneller hangi uygulamaya başvurabilir?', 'Emri küçük parçalara bölüp zamana yaymaya', ['Bütün miktarı açılışta piyasa emriyle satmaya', 'Emri iki kat büyütmeye', 'Fiyat sınırlarını kaldırmaya'], 'Emri parçalamak piyasa etkisini azaltır; algoritmik yürütme stratejileri (ör. VWAP) bu amaçla kullanılır.'),
  ('Aracı kurumların yüksek hızlı bilgisayarlarla saniyenin küçük bölümlerinde çok sayıda emir girip iptal ederek elde ettiği küçük farklara dayanan işlem stratejisine ne denir?', 'Yüksek frekanslı işlem', ['Uzun vadeli değer yatırımcılığı ve temettü stratejisi', 'Endeks fonu stratejisi', 'Düzenli birikim'], 'Yüksek frekanslı işlemde hız ve altyapı avantajıyla çok küçük fiyat farkları çok sayıda işlemle kâra çevrilmeye çalışılır.'),
  ('Bir hissede işlem hacmi gün içinde aniden olağan düzeyin on katına çıkarsa bunun anlamı için hangi yorum en doğrudur?', 'Önemli bir haber ya da yoğun ilgi olabilir ve fiyat riski artmıştır', ['Şirket mutlaka batmaktadır', 'Hisse mutlaka yükselecektir', 'Hacmin hiçbir bilgi içeriği yoktur'], 'Hacim sıçraması bir gelişmeye işaret eder; yön hakkında kesin bilgi vermez, ama oynaklığın arttığını gösterir.'),
  ('Bir hissenin alış-satış makası, hisse fiyatının yüzde 4\'üne kadar açılmış durumdaysa bu hisse hakkında hangisi söylenebilir?', 'İşlem maliyeti yüksek ve likiditesi düşük olabilir', ['Çok likittir, ucuz işlem görür ve çıkış maliyeti düşüktür', 'Temettü ödemez', 'Devlet garantisindedir'], 'Geniş makas, alıp hemen satıldığında kayba uğranacağını gösterir; çoğunlukla az işlem gören hisselerde görülür.'),
  ('Hazine\'nin yurt içinde TLREF gibi bir gösterge faize bağlı olarak ihraç ettiği ve kuponları bu orana göre belirlenen tahvil türü aşağıdakilerden hangisidir?', 'Değişken faizli devlet tahvili', ['İskontolu hazine bonosu', 'Dövizli sabit tahvil', 'Konsol'], 'Kuponları gösterge faize göre güncellenen tahviller değişken faizli olarak adlandırılır.'),
  ('Bir tahvilin bir yıl içinde temerrüde düşme olasılığı yüzde 2, temerrüt hâlinde kayıp oranı yüzde 60 ise beklenen kayıp yüzde kaçtır?', '1,2', ['1,25', '0,6', '120'], 'Beklenen kayıp = temerrüt olasılığı × temerrüt hâlindeki kayıp = 0,02 × 0,60 = yüzde 1,2.'),
  ('Borsa İstanbul Repo Piyasası\'nda gerçekleşen gecelik işlemlerden hesaplanan ve Türk lirası piyasa faizleri için gösterge işlevi gören oran hangisidir?', 'TLREF', ['LIBOR', 'EURIBOR', 'Fed Funds'], 'TLREF (Türk Lirası Gecelik Referans Faiz Oranı), gecelik repo işlemlerinden elde edilen ağırlıklı ortalama faizdir.'),
  ('Şirketlerin kısa vadeli ihtiyaçlarını karşılamak için, genellikle teminatsız ve bir yıldan kısa vadeli olarak ihraç ettiği borçlanma aracı aşağıdakilerden hangisidir?', 'Ticari kâğıt', ['Hisse senedi', 'İntifa senedi', 'Konut sertifikası'], 'Ticari kâğıt, güçlü kredi notlu şirketlerin kısa vadeli kaynak bulmak için çıkardığı iskontolu bir borç senedidir.'),
  ('Bir bankanın belirli bir tutarı, vade sonunda faiziyle ödemeyi taahhüt ederek ihraç ettiği ve ikinci elde satılabilen kısa vadeli belgeye ne denir?', 'Mevduat sertifikası', ['Ortaklık payı', 'Hazine garantisi', 'Emeklilik sözleşmesi'], 'Mevduat sertifikası, banka tarafından ihraç edilen ve devredilebilen vadeli mevduat belgesidir.'),
  ('Bir bankanın başka bir bankaya gecelik, teminatsız borç verirken uyguladığı gösterge faiz olarak uzun yıllar dünya çapında referans alınan ve 2012\'de manipülasyon skandalıyla sarsılan oran hangisidir?', 'LIBOR', ['Dow Jones', 'Nasdaq', 'Basel'], 'LIBOR, büyük bankaların bildirimlerine dayanan referans faizdir; bildirimlerin manipüle edildiği ortaya çıkınca reform sürecine girmiş ve sonradan yerini SOFR gibi işlem tabanlı oranlara bırakmıştır.'),
  ('Para piyasası fonları, Türkiye\'de ve dünyada çoğu zaman \'banka mevduatına alternatif\' olarak tanıtılır. Bu fonların başlıca riski nedir?', 'Faiz ve kredi riski nedeniyle değerin küçük de olsa dalgalanabilmesi', ['Tamamen sıfır riskli olması', 'Hiçbir zaman nakde çevrilememesi', 'Sabit temettü zorunluluğu'], 'Para piyasası fonları kısa vadeli araçlara yatırım yapsa da değerleri günlük küçük dalgalanmalar gösterebilir ve mevduat gibi sigortalı değildir.'),
  ('Bir satım opsiyonu için 4 TL prim ödeyen yatırımcının kullanım fiyatı 50 TL, vade sonu hisse fiyatı 38 TL ise net kârı kaç TL\'dir?', '8', ['12', '4', '0'], 'Opsiyon değeri 50 − 38 = 12 TL; ödenen prim 4 TL çıkarılınca net kâr 8 TL\'dir.'),
  ('Opsiyon fiyatını etkileyen etkenler arasında hisse fiyatındaki beklenen oynaklık arttığında alım opsiyonunun primi genel olarak nasıl değişir?', 'Yükselir', ['Düşer', 'Değişmez', 'Sıfırlanır'], 'Yüksek oynaklık, opsiyonun kârlı bitme ihtimalini artırırken zararı primle sınırlı tuttuğundan hem call hem put primleri artar.'),
  ('Bir yatırımcı endeks vadeli sözleşmesinde 9.500 puandan alım yapıyor. Sözleşme çarpanı 10 TL\'dir. Endeks 9.640 puana çıkınca pozisyonu kapatırsa 1 sözleşmeden elde ettiği kâr kaç TL\'dir?', '1.400', ['140', '14.000', '9.640'], 'Puan farkı 9.640 − 9.500 = 140; 140 × 10 TL = 1.400 TL kâr.'),
  ('Temettü ödemeyen bir hissenin spot fiyatı 100 TL, bir yıllık risksiz faiz yüzde 10 (yıllık) ise bir yıl vadeli teorik vadeli fiyat kaç TL\'dir?', '110', ['110,5', '90', '121'], 'Taşıma maliyeti modeline göre F = S × (1 + r) = 100 × 1,10 = 110 TL.'),
  ('Sabit faiz ödeyip değişken faiz alan bir tarafın, kurgusal anaparası 10 milyon TL olan swapta sabit oran yüzde 8, değişken oran yüzde 6 ise dönem sonunda net ödemesi kaç TL\'dir?', '200.000', ['600.000', '800.000', '2.000.000'], 'Sabit ödeme 800.000, değişken alacak 600.000 TL; fark 200.000 TL net ödemedir.'),
  ('Değişken faizli kredisi olan bir firma faiz artışından korunmak için ne yapabilir?', 'Sabit faiz öderken değişken faiz alacağı bir faiz swapı yapabilir', ['Hisse senedi satabilir', 'Alım opsiyonu yazabilir', 'Altın alıp saklayabilir'], 'Swap sayesinde firmanın kredisine ödediği değişken faiz swaptan gelen değişken faizle karşılanır; sonuçta sabit maliyete dönüşür.'),
  ('Bir ihracatçı üç ay sonra tahsil edeceği dövizin değer kaybından korunmak istiyor. Bu amaçla vadeli kur sözleşmesi (forward) yapması ona hangi imkânı sağlar?', 'Gelecekteki satış kurunu bugünden sabitler', ['Kuru kendisinin belirlemesini ve her durumda kazanmasını', 'Vergi muafiyeti getirir', 'Dövizi garantili biçimde artırır'], 'Forward ile kur bugünden kilitlenir; kur lehe değişse bile bundan yararlanılamaz, ancak belirsizlik ortadan kalkar.'),
  ('Kaldıraçlı vadeli işlem hesabında yatırımcı sözleşme değerinin yüzde 10\'u kadar teminat yatırıyor. Dayanak varlık yüzde 5 düşerse yatırım sermayesinde yaklaşık zarar yüzde kaçtır (uzun pozisyon)?', '50', ['5', '10', '100'], 'Yüzde 5\'lik düşüş sözleşme değerinde olduğundan teminata oranı 5/10 = yüzde 50\'dir.'),
  ('Türkiye\'de yatırım fonlarının alım satımının aracı kurum ve banka şubelerine gitmeden tek bir elektronik platformdan yapılmasını sağlayan sistemin adı nedir?', 'Türkiye Elektronik Fon Alım Satım Platformu (TEFAS)', ['Kamuyu Aydınlatma Platformu (KAP)', 'Merkezi Kayıt Kuruluşu (MKK) Sicili', 'Borsa İstanbul Vadeli Piyasası'], 'TEFAS, Takasbank tarafından işletilir ve farklı kurumların fonlarının tek ekrandan alınıp satılmasını sağlar.'),
  ('Yalnızca yeterli finansal bilgisi ve gelir ya da varlığı olan \'nitelikli yatırımcılara\' satılabilen, daha esnek stratejiler izleyen fon türü hangisidir?', 'Serbest fon (hedge fund)', ['Para piyasası fonu (kısa vadeli borçlanma araçlarına yatırım yapan, herkese açık fon)', 'Endeks fonu', 'Emeklilik fonu'], 'Serbest fonlar kaldıraç, açığa satış ve türev kullanımı gibi daha esnek stratejiler izler; riskleri nedeniyle genellikle nitelikli yatırımcılarla sınırlandırılır.'),
  ('Bir endeks günde yüzde 10 düşüp ertesi gün yüzde 10 yükselirse iki günün sonunda toplam getiri yaklaşık nedir?', 'Yüzde 1 zarar', ['Yüzde 0 kâr ya da zarar, çünkü artış ve düşüş eşit orandadır', 'Yüzde 1 kâr', 'Yüzde 20 kâr'], '100 TL, ilk gün 90 TL\'ye iner; ertesi gün yüzde 10 artışla 99 TL olur. Toplam yüzde 1 zarar vardır; bu, kayıpların geri kazanımında asimetriye örnektir.'),
  ('Yıllık toplam gider oranı (TER) yüzde 1,5 olan fonla yüzde 0,2 olan endeks fonu, brüt getirileri aynı olacak şekilde 20 yıl karşılaştırılırsa hangisi daha çok net birikim sağlar?', 'Düşük giderli fon', ['Yüksek giderli fon', 'İkisi aynı sonucu verir', 'Hiçbir fon kâr sağlayamaz'], 'Giderler her yıl brüt getiriden düşüldüğü için uzun vadede bileşik etkiyle birikimde belirgin fark yaratır.'),
  ('Sektör fonlarıyla geniş endeks fonları karşılaştırıldığında hangi ifade doğrudur?', 'Sektör fonları belirli bir alana yoğunlaştığı için çeşitlendirme düzeyi daha düşüktür', ['Sektör fonları her zaman daha az risklidir', 'Geniş endeks fonları tek şirkete yatırım yapar', 'Sektör fonları sabit faiz öder'], 'Tek sektöre yatırım, o sektöre özgü şoklara yüksek duyarlılık yaratır; geniş endeks fonları farklı sektörlere yayıldığı için bu riski azaltır.'),
  ('Bir yatırımın üç olası senaryosu şöyledir: yüzde 50 olasılıkla yüzde 20 getiri, yüzde 30 olasılıkla yüzde 5 getiri, yüzde 20 olasılıkla yüzde 10 kayıp. Beklenen getiri yüzde kaçtır?', '9,5', ['11,7', '5', '15'], 'Beklenen getiri = 0,5×20 + 0,3×5 + 0,2×(−10) = 10 + 1,5 − 2 = yüzde 9,5.'),
  ('İki hisseden oluşan eşit ağırlıklı bir portföyde hisselerin standart sapmaları yüzde 20 ve yüzde 10\'dur. Aralarındaki korelasyon +1 ise portföyün standart sapması kaçtır?', '15', ['11,2', '5', '30'], 'Korelasyon +1\'de portföy riski ağırlıklı ortalamadır: 0,5×20 + 0,5×10 = yüzde 15; çeşitlendirme yararı yoktur.'),
  ('Bir portföyün yüzde 40\'ı betası 1,5 olan, yüzde 60\'ı betası 0,8 olan hisselerdedir. Portföy betası kaçtır?', '1,08', ['1,15 gibi piyasa betasından daha yüksek bir değer', '0,95', '1,2'], 'Portföy betası ağırlıklı ortalamadır: 0,4×1,5 + 0,6×0,8 = 0,6 + 0,48 = 1,08.'),
  ('Jensen\'in alfa ölçüsüne göre, beklenen getirisi yüzde 10 olması gereken riskte bir portföy yüzde 12 getiri sağlamıştır. Alfa kaçtır?', '+2 puan', ['−2 puan', '+12 puan', '0'], 'Alfa, gerçekleşen getiri eksi risk düzeyine göre beklenen getiridir: 12 − 10 = +2 puan.'),
  ('Ortalama getirisi yüzde 10, standart sapması yüzde 15 olan ve getirileri yaklaşık normal dağılan bir yatırımın getirisinin yaklaşık yüzde 68 olasılıkla hangi aralıkta olması beklenir?', '−5 ile 25 arasında', ['−20 ile 40 arasında', '10 ile 25 arasında', '0 ile 10 arasında'], 'Normal dağılımda gözlemlerin yaklaşık yüzde 68\'i ortalamanın ±1 standart sapma çevresindedir: 10 ± 15 = −5 ile 25.'),
  ('Bir hisse fiyatının bugünkü değişiminin dünkü değişimden bağımsız olduğunu, yani \'rastgele yürüyüş\' izlediğini savunmak hangi sonuca yol açar?', 'Geçmiş fiyat desenleriyle gelecek tahmininin işe yaramayacağı sonucuna', ['Fiyatların sabit kalacağı sonucuna', 'Temettünün artacağı sonucuna', 'Piyasanın kapanması gerektiği sonucuna'], 'Rastgele yürüyüşte yeni bilgi önceden bilinemediği için fiyat değişimleri öngörülemez; teknik analiz sistematik üstünlük sağlayamaz.'),
  ('Son aylarda iyi performans gösteren hisselerin yakın gelecekte de iyi performans gösterme eğilimi taşımasına ne denir?', 'Momentum', ['Rüçhan', 'Çarpan', 'Taban etkisi'], 'Momentum etkisi, geçmişte kazananların kısa-orta vadede kazanmaya devam etme eğilimini anlatan, EMH ile uzlaşması zor bir bulgudur.'),
  ('Robert Shiller\'in 2000\'de yayımlanan kitabı \'Irrational Exuberance\' (Mantıksız Coşku) hangi konuyu işler?', 'Hisse piyasalarındaki aşırı değerlemeyi ve balonların psikolojik köklerini', ['Gayrimenkul vergisini', 'Döviz kuru sabitlemesini', 'Merkez bankası bağımsızlığını'], 'Shiller kitapta teknoloji hisselerindeki aşırı yükselişi ve piyasa psikolojisinin fiyatları temellerinden uzaklaştırmasını anlatır; 2013\'te Nobel Ödülü\'nü aldı.'),
  ('Keynes\'in Genel Teori\'de borsa psikolojisini açıklamak için kullandığı \'güzellik yarışması\' benzetmesinin mantığı nedir?', 'Yatırımcılar şirketin değerinden çok başkalarının neyi güzel bulacağını tahmin etmeye çalışır', ['Yatırımcılar yalnızca bilançoya bakar', 'Fiyatlar tamamen sabittir', 'Şirketler kendi hisselerini oylar'], 'Keynes, hisse alımında gerçek değeri değil çoğunluğun ne düşüneceğini tahmin etme oyununun oynandığını söyleyerek spekülatif davranışı anlatmıştır.'),
  ('Fiyat artıyor diye, hisse gerçek değerinin çok üzerinde olsa bile onu daha yüksek fiyatla satabileceğini umarak alan kişinin dayandığı mantık hangi adla anılır?', 'Daha büyük aptal teorisi', ['Etkin piyasa teorisi', 'Karşılaştırmalı üstünlük', 'Rüçhan teorisi'], 'Daha büyük aptal teorisinde alıcı, daha da yüksek ödeyecek bir sonraki alıcının çıkacağını umar; balonlarda sık görülür.'),
  ('Bir yatırımcı satın aldığı fiyatı \'çıpa\' alarak, hissenin değerinin ancak bu fiyata dönünce adil olacağına inanıyor. Bu hangi eğilimdir?', 'Çıpalama', ['Çeşitlendirme', 'Arbitraj', 'Karşılaştırmalı üstünlük'], 'Çıpalamada karar, ilgisiz de olsa belirli bir başlangıç referansına aşırı bağlı kalınarak verilir.'),
  ('Kahneman ve Tversky\'nin beklenti kuramına göre insanlar kayıplara kazançlara kıyasla nasıl tepki verir?', 'Aynı büyüklükteki kaybı kazançtan yaklaşık iki kat güçlü hisseder', ['Kazançlara daha duyarsızdır', 'Kayıpları hiç önemsemez', 'İkisine eşit tepki verir'], 'Kayıptan kaçınma katsayısı deneylerde yaklaşık 2 civarında bulunmuştur; bu yüzden yarı yarıya 100 TL kazanma ya da 100 TL kaybetme bahsini çoğu kişi reddeder.'),
  ('Bir yatırımcı son haftalarda manşetlerde çok yer alan bir sektörün yükseleceğini düşünüp o sektöre yatırım yapıyor, daha az konuşulan sektörleri ihmal ediyor. Hangi eğilimi sergilemektedir?', 'Kolay hatırlanan bilgiye ağırlık veren erişilebilirlik sezgisini', ['Karşılaştırmalı üstünlüğü', 'Kaldıraç etkisini', 'Rüçhan eğilimini'], 'Erişilebilirlik sezgisinde kolay akla gelen olaylar olduğundan daha olası sanılır.'),
  ('Yatırımcıların yurt içindeki şirketlere, yurt dışına kıyasla orantısız biçimde çok yatırım yapması eğilimine ne ad verilir?', 'Yerel yanlılık (home bias)', ['Çıpalama (ilk görülen fiyata aşırı bağlanma eğilimi)', 'Sürü davranışı', 'Kaldıraç yanılgısı'], 'Home bias, aşina olunan yerel varlıklara aşırı ağırlık vermektir; coğrafi çeşitlendirmeyi azaltır.'),
  ('Sahip olduğu hisseyi, aynı fiyata satın alacak bir kişiye göre daha değerli görmeye neden olan eğilime ne denir?', 'Sahiplik (bağışlama) etkisi', ['Kayıp riski primi', 'Rüçhan etkisi', 'Hacim etkisi'], 'Sahiplik etkisinde kişi sahip olduğu varlığa değer biçerken ona duygusal bağlı kalır ve satış fiyatını yüksek tutar.'),
  ('Son iki yılda piyasanın sürekli yükseldiğini gören bir yatırımcı bunun gelecekte de aynı hızla süreceğini varsayıyor. Bu hangi eğilimdir?', 'Yakın geçmişe aşırı ağırlık verme', ['Yakın geçmişi görmezden gelip yalnızca çok eski veriye bakma', 'Rüçhan anlayışı', 'Vergi yanılgısı'], 'Güncellik yanlılığında son olaylar, uzun dönem verinin önüne geçer ve beklentiler tek yönlü hâle gelir.'),
  ('Roosevelt\'in Mart 1933\'te göreve başladıktan hemen sonra ilan ettiği ve bankaların birkaç gün kapatılmasına yol açan uygulama hangisidir?', 'Banka tatili', ['Altın yasağı', 'Rüçhan düzenlemesi', 'Vergi affı'], 'Roosevelt, bankalara yönelik panik hâlindeki para çekme akınını durdurmak için ulusal banka tatili ilan etti ve Acil Bankacılık Yasası\'yla sağlam bankaları yeniden açtırdı.'),
  ('2007\'de İngiltere\'de Northern Rock müşterilerinin şubelerde kuyruk olup paralarını çekmeye çalışması hangi olguyu simgeler?', 'Banka paniği (bank run)', ['Hisse bölünmesi (pay sayısının artırılması süreci)', 'Rüçhan hakkı', 'Temettü ödemesi'], 'Mevduat sahipleri bankanın ödeme gücünden endişe edince hepsi aynı anda para çektiği için sağlam bankalar bile sıkışabilir.'),
  ('Eylül 2008\'de ABD hükümetinin dev bir sigorta şirketini 85 milyar dolarlık Fed kredisiyle kurtardığı olayda adı geçen şirket hangisidir?', 'AIG', ['Berkshire Hathaway', 'Visa', 'Moody\'s'], 'AIG, kredi temerrüt takasları (CDS) yoluyla verdiği devasa güvenceler nedeniyle ödeme gücünü kaybetmiş ve sistemik riski önlemek için kurtarılmıştır.'),
  ('Eylül 2008\'de ABD\'de konut kredisi piyasasının büyük kısmına garanti veren Fannie Mae ve Freddie Mac\'in hükümet denetimine alınması hangi görüşü güçlendirmiştir?', 'Çok büyük kuruluşların batmasına izin verilemeyeceği', ['Kamu bankalarının kapatılması gerektiği', 'Faizin yasaklanması gerektiği', 'Hisse senetlerinin gereksiz olduğu'], '\'Too big to fail\' görüşüne göre devasa kuruluşların çöküşü sistemin tamamını tehdit ettiğinden devlet müdahale eder; bu da ahlaki tehlike tartışmasını artırır.'),
  ('20 Nisan 2020\'de ABD ham petrol (WTI) vadeli fiyatı tarihte ilk kez nasıl bir değer görmüştür?', 'Negatif', ['Sıfırın tam üstünde', 'Yüzde 100 artış', 'Hiç işlem görmemiştir'], 'Talep çöküşü ve depolama kapasitesinin dolması nedeniyle vadesi gelen kontratı elinde tutmak istemeyenler satıcı olarak ödeme yapmaya razı olunca fiyat negatife düştü.'),
  ('Mayıs 2022\'de çöken Terra (UST) projesi hangi türden bir kripto varlığın kırılganlığını göstermiştir?', 'Algoritmik sabit koinin', ['Altın destekli tokenın', 'Merkez bankası dijital parasının', 'Sertifikalı hisse tokenının'], 'UST, değerini algoritmayla dolara bağlamaya çalışan bir sabit koindi; güven kaybıyla dolar paritesini yitirip değeri hızla sıfıra yaklaştı.'),
  ('Reinhart ve Rogoff\'un 2009 tarihli \'Bu Sefer Farklı\' (This Time Is Different) kitabının temel mesajı nedir?', 'Yüzyıllardır finansal krizler benzer kalıplarla tekrar eder ve \'bu sefer farklı\' inancı hep yanıltıcı olmuştur', ['Krizler artık imkânsızdır', 'Faiz hiç değişmez', 'Borsa her zaman yükselir'], 'Kitap sekiz yüzyıllık veriye dayanarak aşırı borçlanma ve iyimserliğin benzer kriz kalıpları ürettiğini göstermiştir.'),
  ('Kredi kuruluşlarının riskli görünen müşterilere kredi vermeyi birden kısması nedeniyle ekonomide finansman bulmanın zorlaşmasına ne ad verilir?', 'Kredi sıkışıklığı (credit crunch)', ['Yaratıcı yıkım (eski sektörlerin yeni teknolojilerle çökmesi)', 'Mali genişleme', 'Ticaret açığı'], 'Kredi sıkışıklığı, bankaların risk iştahı ve likiditesi daraldığında kredi arzının azalmasıdır ve krizlerde ekonomik daralmayı derinleştirir.'),
  ('George Soros\'un 1992\'de İngiliz sterlini üzerinde yaptığı büyük açığa satışla tanınan olay hangi kavramla birlikte anılır?', 'Bank of England\'ı yenen adam', ['Altın standardının yeniden getirilmesi ve sterlinin devalüasyonu', 'Plaza Anlaşması', 'Marshall Planı'], 'Soros\'un Quantum Fund\'ı sterline karşı büyük pozisyon aldı; İngiltere sterlini ERM\'de tutamayıp Eylül 1992\'de mekanizmadan çıktı.'),
  ('Sistemik risk kavramı bankacılıkta neyi anlatır?', 'Tek bir kurumun ya da piyasanın çöküşünün tüm finansal sisteme yayılma riskini', ['Tek bir bankanın vergi borcunu', 'Hisse fiyatlarının ortalamasını', 'Kredi faizlerinin sabit kalmasını'], 'Finansal kurumlar birbirine borçlu olduğundan bir kurumun batması zincirleme etki yaratabilir; düzenleyiciler bu riski sınırlamaya çalışır.'),
  ('Bir aracı kurum çalışanı müşterisinin verdiği büyük alım emrini piyasaya iletmeden önce kendi hesabıyla aynı hisseden alıyor. Bu uygulamaya ne denir?', 'Müşteri emrinin önüne geçme (front running)', ['Çapraz işlem (iki müşterinin emrinin kurum içinde eşleştirilmesi)', 'Hisse bölünmesi', 'Rüçhan işlemi'], 'Front running\'de emir bilgisi kendi çıkarı için kullanılır; müşterinin emri fiyatı yükselteceği için çalışan öncelikli alımla kazanç sağlar.'),
  ('Aynı kişinin aynı hisseyi kendi kendine alıp satarak sahte hacim izlenimi yaratmasına ne ad verilir?', 'Sahte (yıkama) işlem — wash trading', ['Bölünmüş işlem', 'Takas', 'Kurum içi mahsup'], 'Wash trading\'de mülkiyet gerçekte değişmez; amaç hacmi yapay biçimde şişirip diğer yatırımcıları yanıltmaktır.'),
  ('Kâr amacıyla müşterinin portföyünde gereksiz sıklıkta alım satım yaptırıp komisyon kazanmaya \'churning\' denir. Bu uygulamada kim zarar eder?', 'Müşteri, çünkü masraflar getirisini eritir', ['Devlet vergi kaybettiği için zarar eder, müşteri değil', 'Borsa', 'Şirketin ortakları'], 'Gereksiz işlem sayısı arttıkça ödenen komisyon müşterinin getirisini düşürür; bu davranış etik dışıdır.'),
  ('Bir yatırım şirketinin tanınmış bir dini ya da etnik topluluğun güvenini kullanarak o topluluğun üyelerinden para toplayıp dolandırması hangi türdendir?', 'Yakınlık (affinity) dolandırıcılığı', ['Spoofing', 'Greenshoe', 'Vergi planlaması'], 'Yakınlık dolandırıcılığında ortak kimlik ve güven duygusu, yatırımcının gereken incelemeyi yapmasını engeller.'),
  ('Bir kripto projesinin geliştiricilerinin yatırımcı fonlarını topladıktan sonra projeyi terk edip kaybolmasına ne ad verilir?', 'Halıyı çekme (rug pull)', ['Halka arz (şirketin payları ilk kez halka satması)', 'Sermaye artırımı', 'Geri alım'], 'Rug pull\'da kurucular likiditeyi çekip çıkar ve token değerini sıfırlar; yeterli denetim olmayan yeni projelerde sık görülür.'),
  ('Aynı finans kuruluşunda yatırım danışmanlığı ile kendi adına işlem yapma bölümleri arasında bilgi akışını engelleyen kurumsal düzenlemeye ne denir?', 'Çin Seddi (Chinese wall)', ['Rüçhan duvarı (yeni pay alma hakkını kısıtlayan kural)', 'Arbitraj kuralı', 'Vade köprüsü'], 'Chinese wall, çıkar çatışmasını ve içeriden bilgi sızmasını önlemek için bölümler arasında bilgi alışverişini kısıtlar.'),
  ('Bir yatırım bankasının halka arz sırasında şirketten payların tamamını belirli bir fiyattan satın alıp daha sonra yatırımcılara satmayı taahhüt etmesine ne ad verilir?', 'Kesin taahhütlü (garantili) satış', ['En iyi gayret aracılığı', 'Doğrudan listeleme', 'Rüçhan satışı'], 'Kesin taahhütte satılamayan paylardan doğan risk aracı kurum ya da bankaya aittir; en iyi gayret aracılığında ise satamama riski ihraççıdadır.'),
  ('Hisseleri borsada işlem gören ve portföyünde menkul kıymet ya da gayrimenkul tutan şirket yapısındaki kuruma Türkiye\'de ne ad verilir?', 'Yatırım ortaklığı', ['Aracı kurum', 'Takas kuruluşu', 'Mevduat bankası'], 'Yatırım ortaklıkları, anonim şirket biçiminde kurulur; payları borsada işlem görür ve portföy yönetimi ile ortaklarına getiri sağlamayı amaçlar.'),
  ('Kişiye özel yatırım danışmanlığı sunma yetkisi Türkiye\'de kural olarak hangi kuruluşlara verilir?', 'SPK yetkisine sahip aracı kurumlar ve belirli bankalar', ['Her gerçek kişi, sosyal medya hesabı ve ilgili tüm kuruluşlar', 'Tüm sosyal medya hesaplarına', 'Sadece sigorta acentelerine'], 'Kişisel yatırım danışmanlığı izne tabi bir faaliyettir; izinsiz verilen tavsiyeler düzenleyici kurumların yaptırım alanına girer.'),
  ('Uluslararası Menkul Kıymetler Komisyonları Örgütü (IOSCO) hangi alanda standart belirler?', 'Menkul kıymet piyasalarının düzenlenmesi ve yatırımcıların korunması', ['Merkez bankası rezervleri', 'Uluslararası ticaret tarifeleri', 'Döviz kuru rejimleri'], 'IOSCO, dünya genelindeki sermaye piyasası düzenleyicilerinin ilkelerini ve iş birliğini belirleyen uluslararası kuruluştur.'),
  ('Bankaların sermaye yeterliliği oranı hangi iki büyüklüğün oranıyla hesaplanır?', 'Özkaynak / risk ağırlıklı varlıklar', ['Mevduat / verilen krediler toplamı ve karşılık oranı', 'Net kâr / toplam varlık', 'Hazine bonosu / mevduat'], 'Sermaye yeterlilik oranı, bankanın kayıplarını karşılayacak sermayenin riske göre ağırlıklandırılmış varlıklara oranıdır.'),
  ('2008 krizi sonrası G20 liderlerinin 2009\'da küresel finansal istikrarı izlemek için güçlendirdiği kuruluş hangisidir?', 'Finansal İstikrar Kurulu (FSB)', ['Dünya Ticaret Örgütü (ticaret uyuşmazlıklarını çözen kuruluş)', 'OPEC', 'Dünya Ekonomik Forumu'], 'FSB, küresel finansal sistemin risklerini izleyip düzenleme önerileri geliştiren, G20 ile birlikte çalışan kuruluştur.'),
  ('Varil fiyatı 80 dolar olan ham petrolün litre başına maliyeti yaklaşık kaç dolardır? (1 varil ≈ 159 litre)', '0,50', ['0,0503', '5', '1,27'], '80 / 159 ≈ 0,50 dolar; ham petrol fiyatı rafine ürün fiyatından ve vergilerden ayrıdır.'),
  ('London Metal Exchange (LME) hangi tür emtia ticaretinde dünyanın önde gelen borsalarındandır?', 'Bakır, alüminyum, çinko gibi sanayi metallerinde', ['Kakao ve kahvede', 'Doğal gazda', 'Hisse senedinde'], 'LME, 1877\'de kurulmuş ve temel metal vadeli sözleşmeleriyle küresel referans fiyatlar oluşturan bir borsadır.'),
  ('Bakıra neden bazen \'Doktor Bakır\' lakabı verilir?', 'Fiyatı genellikle küresel ekonomik faaliyetin sağlığını yansıttığı düşünüldüğü için', ['Tıpta kullanıldığı için', 'Çok pahalı olduğu için', 'Gıda katkısı olduğu için'], 'Bakır inşaat, elektrik ve sanayide yaygın kullanıldığından fiyatı sanayi talebinin ve ekonomik büyümenin göstergesi sayılır.'),
  ('Kakaoda dünya üretiminin yarısından fazlasını birlikte sağlayan iki Batı Afrika ülkesi hangileridir?', 'Fildişi Sahili ve Gana', ['Nijerya, Mısır ve Güney Afrika Cumhuriyeti', 'Etiyopya ve Kenya', 'Fas ve Tunus'], 'Fildişi Sahili ve Gana, dünya kakao arzının büyük bölümünü karşılar; bölgedeki hava ve siyasi gelişmeler fiyatı doğrudan etkiler.'),
  ('Tarım ürünü emtia fiyatlarında kuraklık gibi hava olaylarının etkisi neden belirgindir?', 'Arz kısa sürede artırılamadığı ve talep fiyata duyarsız olduğu için fiyat sert tepki verir', ['Tarım ürünleri hiç tüketilmediği için', 'Hava olayları fiyatı etkilemez', 'Borsalar hava durumuna göre kapanır'], 'Tarımsal üretimde arz mevsime bağlıdır ve talep (gıda) esnek değildir; bu yüzden arz şoku büyük fiyat değişimi yaratır.'),
  ('Gümüşün altından ayrılan temel özelliklerinden biri nedir?', 'Sanayide (elektronik, güneş paneli) çok kullanılması ve yüksek elektrik iletkenliği', ['Hiç sanayide kullanılmaması', 'Daha az bulunması ve hiç işlenememesi', 'Merkez bankalarının resmî para olarak tutması'], 'Gümüş bütün metaller arasında en yüksek elektrik ve ısı iletkenliğine sahiptir; sanayi talebi fiyatı altına göre daha dalgalı yapabilir.'),
  ('Platin için dünyanın en büyük üreticisi olan ülke hangisidir?', 'Güney Afrika', ['Rusya', 'Avustralya', 'Brezilya'], 'Platin üretimi büyük ölçüde Güney Afrika\'daki Bushveld bölgesinde yapılır; ülkedeki grev ve enerji sorunları arz riskini artırır.'),
  ('Platin ve paladyumun en önemli sanayi kullanım alanlarından biri hangisidir?', 'Araçların egzoz gazı katalitik konvertörleri', ['Gıda koruma, ambalaj ve içecek şişeleme sanayi', 'Kâğıt üretimi', 'Tekstil boyama'], 'Platin ve paladyum zehirli egzoz gazlarını daha az zararlı bileşiklere dönüştüren katalitik konvertörlerde kullanılır; otomotiv talebi fiyatları belirler.'),
  ('Emtia fiyatlarının son derece yüksek seyrettiği ve Çin\'in sanayileşmesiyle birlikte 2000\'lerde uzun süreli yükselişlerin yaşandığı döneme iktisatçılar çoğunlukla ne ad verir?', 'Emtia süper döngüsü', ['Kara kuğu', 'Lale çılgınlığı', 'Likidite tuzağı'], 'Süper döngü, talebin yapısal artışıyla yıllar süren emtia fiyat yükselişi dönemlerini ifade eder.'),
  ('Emtia fiyatlarındaki artışın genel enflasyon üzerindeki etkisi için hangisi doğrudur?', 'Girdi maliyetlerini artırarak enflasyonu yükseltme eğilimindedir', ['Enflasyonu kesinlikle düşürür', 'Enflasyonla ilişkisi yoktur', 'Sadece hisse fiyatlarını etkiler'], 'Enerji ve tarım ürünleri üretim ve tüketim maliyetlerine girdiği için emtia fiyat artışları maliyet kaynaklı enflasyona yol açabilir.'),
  ('Fiziki teslimat yerine kâr-zarar farkının nakit olarak ödendiği vadeli sözleşme uzlaşma yöntemine ne denir?', 'Nakit uzlaşma', ['Fiziki uzlaşma', 'Bölünmüş uzlaşma', 'Rüçhan uzlaşması'], 'Nakit uzlaşmalı sözleşmelerde mal teslim edilmez; sözleşme fiyatı ile vade fiyatı arasındaki fark ödenir.'),
  ('Emtia yatırımının hisse senedi ve tahvil portföyüne eklenmesinin olası faydası nedir?', 'Enflasyon dönemlerinde ve farklı döngülerde portföy getirisini çeşitlendirmesi', ['Getiriyi garanti etmesi', 'Vergi ödemeyi ortadan kaldırması', 'Riski sıfırlaması'], 'Emtia getirileri hisse ve tahvilden farklı etkenlerle belirlendiği için çeşitlendirme sağlayabilir, ancak riski ve oynaklığı yüksek olabilir.'),
  ('Yatırımcıların fiziki altın yerine \'kâğıt altın\' (sertifika, hesap) tercih etmesinin olası riski hangisidir?', 'Karşı taraf riski ve gerçek altına erişimde sorun yaşanabilmesi', ['Altının tamamen değersizleşmesi', 'Vergi borcunun sıfırlanması', 'Fiyatın sabitlenmesi'], 'Kâğıt altında karşılığın tutulduğu kuruluşun yükümlülüğünü yerine getirme riski vardır; fiziki altında ise saklama ve güvenlik maliyeti bulunur.'),
  ('Üç yıl boyunca her yıl sonunda 1.000 TL alınacaktır. İskonto oranı yüzde 10 ise bu ödeme serisinin bugünkü değeri yaklaşık kaç TL\'dir?', '2.487', ['2.745', '2.700', '2.310'], '1.000/1,1 + 1.000/1,21 + 1.000/1,331 ≈ 909 + 826 + 751 ≈ 2.487 TL; toplam nakit 3.000 olsa da gelecekteki ödemeler iskontolanır.'),
  ('Ödemelerin dönem sonu yerine dönem başında yapıldığı bir seri (peşin ödemeli annüite) için bugünkü değer, aynı koşullardaki dönem sonu serisine göre nasıl olur?', 'Daha yüksektir, çünkü her ödeme bir dönem daha erken alınır', ['Daha düşüktür', 'Aynıdır', 'Sıfırdır'], 'Peşin ödemeli serinin bugünkü değeri, dönem sonu serisinin (1 + r) katıdır; örneğin yüzde 10 iskontoda yaklaşık yüzde 10 daha yüksektir.'),
  ('Bir projede başlangıç yatırımı 1.000 TL; nakit girişleri 1., 2., 3. yılların sonunda 400, 500 ve 600 TL\'dir. İskonto oranı yüzde 10 ise net bugünkü değer yaklaşık kaç TL\'dir?', '228', ['500', '0', '1.500'], 'Bugünkü değerler 363,6 + 413,2 + 450,8 = 1.227,6; yatırım çıkarılınca NBD ≈ 228 TL. Pozitif NBD projeyi cazip kılar.'),
  ('Karlılık endeksi (profitability index) bir projede neyi gösterir?', 'Nakit girişlerinin bugünkü değerinin başlangıç yatırımına oranını', ['Net kârın satışlara oranını', 'Borcun özkaynağa oranını', 'Temettünün fiyata oranını'], 'PI = nakit girişlerinin bugünkü değeri / yatırım tutarı; 1\'in üzerindeyse NBD pozitiftir. Sermayenin sınırlı olduğu durumda projeleri sıralamaya yarar.'),
  ('İskontolu geri ödeme süresi, basit geri ödeme süresinden hangi bakımdan ayrılır?', 'Nakit akışlarını iskonto ederek paranın zaman değerini dikkate alır', ['Nakit akışlarını hiç dikkate almaz', 'Yalnızca kâr rakamını kullanır', 'Enflasyonu sıfır varsayar'], 'İskontolu yöntemde her yılın nakit girişi iskonto edilir; bu yüzden geri ödeme süresi basit yönteme göre genelde daha uzundur.'),
  ('Bir şirketin yeni bir üretim hattı yatırımı için kullandığı iskonto oranının yüksek tutulması hangi duruma işaret eder?', 'Projenin riskli olduğunun ya da sermaye maliyetinin yüksek olduğunun', ['Projenin kesinlikle kârlı olduğunun', 'Projenin hiç nakit üretmeyeceğinin', 'Enflasyonun düşük olduğunun'], 'İskonto oranı, yatırımcının talep ettiği getiriyi yansıtır; risk ve sermaye maliyeti arttıkça oran yükselir ve NBD azalır.'),
  ('Bir hissenin gelecek yıl hisse başına temettüsü 5 TL, temettülerin yıllık yüzde 5 büyümesi ve istenen getiri yüzde 10 ise Gordon büyüme modeline göre hisse değeri kaç TL\'dir?', '100', ['100,5', '75', '200'], 'P = D1 / (r − g) = 5 / (0,10 − 0,05) = 100 TL.'),
  ('İndirgenmiş nakit akışı değerlemesinde \'terminal değer\' neyi ifade eder?', 'Açık tahmin döneminin ardından kalan sonsuz dönemin vade sonundaki bugünkü değeri', ['Şirketin bugünkü temettüsünü', 'Şirketin son bilanço kârını', 'Şirketin tasfiye bedelini'], 'Tahmin dönemi sonrasındaki nakit akışları genellikle büyüme oranı ve iskonto oranıyla bir sonsuz seri olarak değerlenir ve bu değer terminal değer diye anılır.'),
  ('Karşılaştırmalı çarpan yöntemiyle değerleme yapan bir analist neye dayanır?', 'Benzer şirketlerin F/K, PD/DD gibi çarpanlarına', ['Şirketin kuruluş yılına', 'Şirketin çalışan sayısının yarısına', 'Merkez bankası faizine'], 'Çarpan analizinde benzer sektör ve büyüklükteki şirketlerin işlem çarpanları değerlenecek şirkete uygulanarak adil fiyat tahmin edilir.'),
  ('Bir şirketin sermaye maliyeti (WACC) hangi bileşenlerin ağırlıklı ortalamasıdır?', 'Özkaynak maliyeti ve vergi sonrası borç maliyeti', ['Temettü ve vergi tutarlarının ağırlıklı ortalamasını', 'Faiz geliri ve kira geliri', 'Satış ve amortisman'], 'WACC, finansman kaynaklarının (özkaynak ve borç) sermaye yapısındaki ağırlıklarına göre bulunan ortalama maliyetidir.'),
  ('Kurumlar vergisinin olduğu dünyada borç kullanmanın şirkete sağladığı avantaja ne denir?', 'Faiz vergi kalkanı', ['Rüçhan avantajı', 'Temettü kalkanı', 'Geri alım kalkanı'], 'Faiz giderleri vergiden düşüldüğü için borç, şirketin vergi yükünü azaltır; ancak aşırı borç iflas riskini artırır.'),
  ('Bağımsız denetçi, finansal tabloların önemli hatalardan arınmış ve gerçeği doğru yansıttığı kanaatine varırsa hangi tür görüş verir?', 'Olumlu görüş', ['Şartlı görüş', 'Olumsuz görüş', 'Görüş bildirmekten kaçınma'], 'Olumlu görüş, tabloların önemli yanlışlık içermediği anlamına gelir; diğer görüş türleri sorun ya da kısıt bulunduğunu işaret eder.'),
  ('Bir şirketin net kârı 100 milyon TL iken faaliyetlerinden nakit akışı yalnızca 20 milyon TL ise bu durum yatırımcı için neyi düşündürmelidir?', 'Kâr kalitesinin düşük olabileceğini ve alacak ya da stok birikiminin sorgulanması gerektiğini', ['Şirketin çok sağlıklı olduğunu', 'Vergi indiriminin başladığını', 'Temettünün otomatik arttığını'], 'Kâr tahakkuka dayalıdır; nakit akışı uzun süre kârın gerisinde kalıyorsa gelirlerin tahsil edilememesi ya da şişirilmiş kâr söz konusu olabilir.'),
  ('Konsolide finansal tablo neyi gösterir?', 'Ana ortaklık ile bağlı ortaklıkların tek bir ekonomik bütün olarak birleştirilmiş durumunu', ['Yalnızca ana şirketin kendi bilançosunu', 'Şirketin vergi beyannamesini', 'Şirketin hisse fiyat geçmişini'], 'Konsolidasyonda grup içi işlemler elenir ve ana şirketle kontrol ettiği şirketlerin varlık, borç ve sonuçları birlikte sunulur.'),
  ('Şirketin satışları artarken alacaklarının satışlardan çok daha hızlı artması yatırımcı için hangi olası sorunu gösterir?', 'Tahsilat sorunu ya da gelirin agresif muhasebeleştirilmesi riski', ['Stokların azalması', 'Borçların bitmesi', 'Faiz gelirinin yükselmesi'], 'Alacak büyümesi satış büyümesini aşıyorsa gelirler kredili satışlarla şişirilmiş olabilir ve tahsil edilememe riski artar.'),
  ('Bir şirketin kârında gayrimenkul satışından kaynaklanan tek seferlik gelirin payı çok yüksekse analist hangi yorumu yapmalıdır?', 'Sürdürülebilir faaliyet kârının daha düşük olduğunu, kârın tekrarlanmayabileceğini', ['Kâr kalitesi çok yüksektir', 'Gelecek yıl aynı kârın garanti olduğunu', 'Hisse fiyatı mutlaka düşecektir'], 'Olağan dışı gelirler gelecekte tekrarlanmayabilir; bu yüzden analistler normalleştirilmiş kâr üzerinden değerleme yapar.'),
  ('Bir şirketin satın alma bedelinin büyük bölümünü borçla finanse edip bu borcu satın alınan şirketin nakit akışlarıyla ödemeyi hedeflediği işlem türüne ne denir?', 'Kaldıraçlı satın alma (LBO)', ['Bedelsiz sermaye artırımı (iç kaynaklardan yeni pay verilmesi)', 'Halka arz', 'Doğrudan listeleme'], 'LBO\'da fon yöneticileri hedef şirketi yüksek borçla satın alır ve borcu şirketin nakit akışlarıyla geri öder; risk ve getiri potansiyeli yüksektir.'),
  ('Bir şirketin nakit fazlasını temettü yerine pay geri alımıyla dağıtmasının temettüye kıyasla olası avantajı nedir?', 'Ortakların vergilendirme zamanlamasını seçebilmesi ve hisse başına kârın artması', ['Hisse fiyatını sıfırlaması', 'Şirketi kapatması', 'Borçları artırması'], 'Geri alımda satış yapan ortak vergilendirilir, satmayanlar ise payını artırır ve hisse başına kâr yükselir; ayrıca şirket için daha esnek bir dağıtım yoludur.'),
  ('Bir şirket, yönetimin hissedarlar yerine kendi çıkarına hareket etme riskini azaltmak için yönetici ücretini hisse performansına bağlıyor. Bu düzenleme hangi sorunu hafifletmeyi amaçlar?', 'Vekâlet (agency) sorununu', ['Likidite tuzağını', 'Ters seçimi', 'Para yanılsamasını'], 'Vekâlet sorununda yöneticiler ortakların çıkarına değil kendi çıkarına davranabilir; hisse bazlı ödüller çıkarları hizalamaya çalışır.'),
  ('Temettü dağıtımına Türkiye\'de anonim şirketlerde genel olarak kim karar verir?', 'Genel kurul (yönetim kurulunun teklifiyle)', ['Merkez Bankası (para politikası kurulu kararıyla)', 'Hazine', 'Takasbank'], 'Net dönem kârının dağıtımı yönetim kurulu önerisi üzerine genel kurul tarafından karara bağlanır.'),
  ('Bir şirketin bilançosunda kısa vadeli borçlarının çoğunun, stok ve alacak gibi daha geç nakde dönüşen kalemlerle finanse edilmesi hangi riski gösterir?', 'Likidite ve vade uyumsuzluğu riski', ['Kur riski', 'Temettü riski', 'Sektör teşvik riski'], 'Kısa vadeli borçlar önce ödenmek zorunda kalırken varlıklar geç nakde döndüğünden şirket ödeme güçlüğüne düşebilir.'),
  ('Aynı sektörde faaliyet gösteren iki şirketten A\'nın faaliyet kâr marjı yüzde 20, B\'nin yüzde 8\'dir. Bu karşılaştırmadan hangi sonuç çıkarılabilir?', 'A, aynı satış başına faaliyet kârı bakımından daha verimli olabilir', ['B kesinlikle daha değerlidir', 'İki şirketin hisse fiyatı eşittir', 'Faaliyet marjı karşılaştırması anlamsızdır'], 'Aynı sektördeki şirketlerde yüksek faaliyet marjı, maliyet yönetimi ve fiyatlama gücü üstünlüğüne işaret edebilir; yine de büyüme ve borç gibi diğer etkenlere de bakılmalıdır.'),
  ('ABD\'de 1960\'ta çıkarılan yasayla küçük yatırımcının büyük ticari gayrimenkullere ortak olabilmesini sağlayan yapıya ne ad verilir?', 'REIT', ['ETF', 'ADR', 'SPAC'], 'REIT\'ler gayrimenkul gelirini üreten şirketlerdir ve vergi avantajı karşılığında kazançlarının büyük kısmını ortaklarına dağıtmak zorundadır.'),
  ('Ticari gayrimenkulde kapitalizasyon oranı (cap rate) nasıl hesaplanır?', 'Yıllık net işletme geliri / mülk değeri', ['Mülk değeri / kira', 'Net kâr / özkaynak', 'Borç / mülk değeri'], 'Cap rate, giderler düşüldükten sonra kalan yıllık net gelirin mülkün piyasa değerine oranıdır; getiri ve değerleme karşılaştırması için kullanılır.'),
  ('Bir ofis binası yıllık 500.000 TL net işletme geliri sağlıyor ve piyasada yüzde 5 cap rate ile fiyatlanıyorsa değeri yaklaşık kaç TL\'dir?', '10.000.000', ['2.500.000', '25.000.000', '500.000'], 'Değer = net gelir / cap rate = 500.000 / 0,05 = 10.000.000 TL.'),
  ('Faizlerin yükselmesi, kira getirisine dayalı gayrimenkul değerlerini genel olarak nasıl etkiler?', 'İstenen getiri artacağından değerler baskılanma eğilimindedir', ['Değerler her zaman artar', 'Etkisi yoktur', 'Kiralar sıfırlanır'], 'Yüksek faiz, alternatif yatırımların getirisini yükselttiği ve iskonto oranını artırdığı için aynı kira geliri daha düşük bir değere denk gelir.'),
  ('Yatırım amaçlı alınan gayrimenkulün değerini objektif biçimde belirlemek için GYO ve fonlarda hangi belge zorunludur?', 'Lisanslı kuruluşça hazırlanmış değerleme raporu', ['Hisse senedi sertifikası', 'Komisyon makbuzu', 'Vergi levhası'], 'Sermaye piyasası mevzuatı, portföye alınan gayrimenkullerin bağımsız ve yetkili değerleme kuruluşlarınca değerlenmesini öngörür.'),
  ('Bitcoin ağında yeni bir bloğun yaklaşık kaç dakikada bir üretilecek şekilde tasarlandığı kabul edilir?', '10', ['1', '60', '0,1'], 'Madencilik zorluğu otomatik ayarlanarak ortalama blok süresi yaklaşık 10 dakikada tutulur.'),
  ('Bir Bitcoin kaç satoshiye bölünebilir?', '100 milyon', ['1 milyon', '1.000', '21 milyon'], '1 satoshi, bir Bitcoin\'in yüz milyonda biridir; ağın en küçük birimi bu değerdir.'),
  ('Ethereum\'un Eylül 2022\'de iş ispatından (proof of work) vazgeçerek geçtiği mekanizma hangisidir?', 'Hisse ispatı (proof of stake)', ['İş ispatı (proof of work, madencilik tabanlı sistem)', 'Merkezî onay sistemi', 'Kâğıt defter sistemi'], 'The Merge ile Ethereum, madencilik yerine doğrulayıcıların coin kilitlediği hisse ispatı sistemine geçti ve enerji tüketimini büyük ölçüde azalttı.'),
  ('Hisse ispatı sisteminde \'staking\' ne anlama gelir?', 'Kripto varlığı doğrulama sürecine katılmak için kilitlemek ve karşılığında ödül kazanmak', ['Kripto varlığı borsada hızla satmak', 'Kripto varlığı yakmak', 'Cüzdan şifresini değiştirmek'], 'Staking\'de katılımcı coinlerini ağda doğrulama görevi için kilitler, yanlış davranış durumunda cezalandırılabilir, karşılığında ağdan ödül alır.'),
  ('Bir kripto ağında çoğunluk işlem gücünü ele geçiren kişi ya da grubun işlem geçmişini değiştirmeye çalışması hangi saldırı olarak bilinir?', '%51 saldırısı', ['Rüçhan saldırısı', 'Fiyat saldırısı', 'Hisse bölünmesi saldırısı'], 'Ağın hesaplama gücünün çoğunluğunu kontrol eden taraf işlemleri geri alıp çifte harcama yapabilir; büyük ağlarda bu çok pahalıdır.'),
  ('Bir kripto ağının yazılım kurallarında yapılan ve eski sürümle uyumsuz yeni bir zincir yaratan değişikliğe ne ad verilir?', 'Sert çatallanma (hard fork)', ['Yumuşak çatallanma (eski sürümle uyumlu kural değişikliği)', 'Madencilik zorluk ayarı', 'Kayıp anahtar'], 'Hard fork\'ta ağ kuralları geriye dönük uyumsuz biçimde değişir; 2017\'de Bitcoin Cash bu yolla Bitcoin\'den ayrılmıştır.'),
  ('Kripto cüzdanlarında \'soğuk cüzdan\' ile \'sıcak cüzdan\' arasındaki temel fark nedir?', 'Soğuk cüzdan internete bağlı değildir, sıcak cüzdan çevrimiçi olduğundan saldırı riski daha yüksektir', ['Soğuk cüzdan sadece nakit içindir', 'Sıcak cüzdan hiç kullanılmaz', 'İkisi aynıdır'], 'Anahtarların internetten uzak tutulduğu soğuk cüzdanlar saldırılara daha dayanıklıdır; sıcak cüzdanlar kolay erişim sağlar ama daha çok risk taşır.'),
  ('2014\'te dünyanın en büyük Bitcoin borsalarından biri olan Mt. Gox\'un çöküşü hangi sonucu doğurmuştur?', 'Çok sayıda kullanıcının Bitcoin\'lerine erişememesi ve kripto borsalarının güvenilirliğinin sorgulanması', ['Bitcoin\'in yasaklanması', 'Merkez bankalarının Bitcoin\'i resmî para ilan etmesi', 'Altın standardının dönmesi'], 'Mt. Gox, hırsızlık ve güvenlik zafiyetleri sonrası iflas etti; bu olay kripto varlıkların saklama ve düzenleme risklerini görünür kıldı.'),
  ('Merkezi olmayan finans (DeFi) uygulamalarının temel fikri nedir?', 'Aracı kurum ya da banka olmadan akıllı sözleşmelerle kredi, takas gibi hizmetlerin sunulması', ['Devletin tüm bankaları devralması', 'Kâğıt senetle ticaret', 'Yalnızca altın alım satımı'], 'DeFi, blokzincir üzerindeki akıllı sözleşmelerle finansal hizmetleri aracısız biçimde sunmaya çalışır; akıllı sözleşme açıkları gibi riskler taşır.'),
  ('Bir girişimin kendi kripto tokenını yatırımcılara satarak fon topladığı ve 2017-2018 döneminde yaygınlaşan yöntem hangisidir?', 'ICO (ilk koin arzı)', ['Halka arz (IPO, şirket paylarının borsaya ilk satışı)', 'Bedelsiz artırım', 'Repo'], 'ICO\'da proje sahipleri yeni bir token satışıyla fon toplar; hukuki belirsizlik ve dolandırıcılık riski yüksektir.'),
  ('Bir girişime yatırım yapmadan önceki şirket değerine ne ad verilir?', 'Yatırım öncesi değerleme (pre-money)', ['Yatırım sonrası değerleme (post-money)', 'Net defter değeri', 'Tasfiye değeri'], 'Pre-money, yeni fon girmeden önceki şirket değeridir; post-money ise yeni yatırım eklendikten sonraki değerdir.'),
  ('Bir girişim 2 milyon TL yatırım karşılığında yüzde 20 pay veriyorsa yatırım öncesi şirket değeri kaç milyon TL\'dir?', '8', ['10', '2', '12'], 'Yatırım sonrası değer = 2 / 0,20 = 10 milyon TL; yatırım öncesi değer 10 − 2 = 8 milyon TL.'),
  ('Kurucuların şirkette yüzde 60 payı vardır. Yeni yatırım turunda yatırımcılara, tur sonrası şirketin yüzde 25\'ini oluşturacak yeni paylar çıkarılırsa kurucuların payı kaç olur?', '45', ['35,5', '60', '75'], 'Yeni yatırımcı yüzde 25 alınca mevcut tüm ortakların payı 0,75 ile çarpılır: 60 × 0,75 = yüzde 45.'),
  ('Bir girişimin ürününü geliştirdikten sonra pazarda gelir elde edebilene kadar yaşadığı nakit sıkıntısı dönemine ne ad verilir?', 'Ölüm vadisi', ['Altın kesişim', 'Karşı taraf riski', 'Kara kuğu'], 'Ölüm vadisi, giderlerin yüksek ve gelirin henüz yetersiz olduğu, birçok girişimin finansman bulamadığı dönemdir.'),
  ('Girişim sermayesi portföylerinde yatırımların küçük bir bölümünün getirinin büyük kısmını sağlaması ne ile açıklanır?', 'Kuvvet yasası (power law) dağılımıyla', ['Normal dağılım', 'Eşit dağılımla', 'Rüçhan hakkıyla'], 'Girişim yatırımlarında çok sayıda yatırım zarar ederken birkaç büyük başarı fonun getirisini belirler; bu yüzden fonlar geniş portföy kurar.'),
  ('Bir girişimcinin şirketine yatırım yapan fonun yatırımını nakde çevirdiği iki yaygın çıkış yolu hangileridir?', 'Halka arz ve başka bir şirkete satış (birleşme-devralma)', ['Bedelsiz artırım ve temettü dağıtımı (iç kaynak kullanımı)', 'Repo ve swap', 'Hisse bölünmesi ve ters bölünme'], 'Girişim sermayesi yatırımcıları payını borsaya açılarak ya da şirketin devralınmasıyla satar.'),
  ('Bireylerin birbirine aracı bir platform üzerinden faizle borç verdiği kitle fonlaması türüne ne ad verilir?', 'Borç temelli (P2P) kitle fonlaması', ['Bağış temelli kitle fonlaması', 'Ödül modeli', 'Pay modeli'], 'P2P modelinde platform borç verenle borçluyu bir araya getirir; kredi riski yatırımcıya aittir.'),
  ('Girişim sermayesi fonlarının tipik yaşam süresi ve likidite özelliği için hangisi doğrudur?', 'Yatırım uzun yıllar (yaklaşık 10 yıl) bağlı kalır ve erken çıkış kolay değildir', ['Yatırımcı her gün çıkış yapabilir', 'Fon sadece günlük işlem yapar', 'Fon sürekli temettü öder'], 'Girişim ve özel sermaye fonları uzun vadeli kapalı fonlardır; yatırımcı fon süresi boyunca paraya genellikle erişemez.'),
  ('Serbest fonlarda \'yüzde 2 ve yüzde 20\' ücret düzeni ne anlama gelir?', 'Yıllık yönetim ücreti yüzde 2, kârdan performans ücreti yüzde 20', ['Yıllık getiri sınırı yüzde 2 ve yüzde 20', 'Giriş yüzde 2 çıkış yüzde 20 komisyon', 'Vergi oranları'], 'Klasik serbest fon ücreti yönetilen varlığın yüzde 2\'si kadar yönetim ücretini ve elde edilen kârın yüzde 20\'si kadar performans ücretini kapsar.'),
  ('Özel sermaye fonlarının ilk yıllarında yatırımcı getirisinin negatif görünmesi ve sonra yükselmesini anlatan grafik şekline ne denir?', 'J eğrisi', ['Laffer eğrisi', 'Phillips eğrisi', 'Lorenz eğrisi'], 'İlk yıllarda ücretler ve yatırım gider olarak yansırken değer artışı geç gerçekleştiğinden getiri önce düşer, sonra yükselir.'),
  ('2017\'de Christie\'s müzayedesinde Leonardo da Vinci\'ye atfedilen \'Salvator Mundi\' tablosunun yaklaşık 450 milyon dolara satılması sanat yatırımı için neyi simgeler?', 'Sanat piyasasında olağanüstü fiyatların mümkün olduğunu, ancak likiditenin düşük ve değerlemenin öznel olduğunu', ['Sanatın hisse gibi günlük işlem gördüğünü', 'Sanatın faiz getirdiğini', 'Sanatın vergisiz olduğunu'], 'Sanat eserleri yüksek fiyatlara ulaşsa da tekil, değerlemesi uzmanlığa dayalı ve satışı zor varlıklardır.'),
  ('Y Combinator gibi girişim hızlandırıcıların temel işlevi nedir?', 'Erken aşamadaki girişimlere kısa programda mentorluk, ağ ve başlangıç fonu sağlamak', ['Girişimlerin vergisini ödemek', 'Merkez bankası politikası belirlemek', 'Borsada hisse fiyatını sabitlemek'], 'Hızlandırıcılar belirli bir pay karşılığında yoğun bir programla girişimlerin hızla büyümesine ve sonraki yatırım turlarına hazırlanmasına yardımcı olur.'),
  ('Piyasa terminolojisinde fiyatın zirvesinden yüzde 10 civarında geri çekilmesine ne denir?', 'Düzeltme (correction)', ['Ayı piyasası (zirveden yüzde 20\'yi aşan düşüş dönemi)', 'Balon', 'Temerrüt'], 'Genel kabule göre yüzde 10-20 arası düşüş düzeltme sayılır; yüzde 20 üzeri düşüş ayı piyasası olarak adlandırılır.'),
  ('Çok düşük fiyatlı, genellikle az bilinen ve yüksek riskli küçük şirket hisselerine ne ad verilir?', 'Penny stock', ['Blue chip', 'Defansif hisse', 'Endeks hissesi'], 'Penny stock\'lar düşük fiyatları, düşük likiditeleri ve manipülasyona açık yapıları nedeniyle çok risklidir.'),
  ('Uzun süreli bir düşüşten sonra fiyatın kısa süreli toparlanıp tekrar düşmesini anlatan jargon hangisidir?', 'Ölü kedi sıçraması (dead cat bounce)', ['Altın kesişim (kısa ortalamanın uzun ortalamayı yukarı kesmesi)', 'Kapanış primi', 'Hisse bölünmesi'], 'Dead cat bounce, düşüş trendi içinde yalancı bir toparlanmadır; sıçrama sonrası fiyat yeniden düşer.'),
  ('Bir hissenin açığa satış yapanların zorunlu geri alımıyla hızla yükselmesine ne ad verilir?', 'Short squeeze (açık pozisyon sıkışması)', ['Pay bölünmesi (hisse sayısının artırılıp fiyatın düşürülmesi)', 'Temettü sıçraması', 'Rüçhan satışı'], 'Fiyat beklenmedik biçimde yükselince açığa satıcılar zararı kapatmak için hisse alır; bu alımlar fiyatı daha da yukarı iter.'),
  ('Ocak 2021\'de küçük yatırımcıların sosyal medyada örgütlenerek çok sayıda açığa satış yapılmış bir hisseyi toplu aldığı ve fiyatın birkaç günde katlandığı olay hangi hisseyle anılır?', 'GameStop', ['Tesla', 'Apple', 'Coca-Cola'], 'GameStop olayı, açığa satış pozisyonlarının sıkışmasıyla fiyatın aşırı yükselmesini ve sosyal medyanın piyasa üzerindeki etkisini gösterdi.'),
  ('Hisse senedinin serbest dolaşımdaki payı (free float) neyi ifade eder?', 'Stratejik ortaklar ve devlet gibi sürekli elde tutanlar dışında borsada işlem görebilen pay oranını', ['Şirketin tüm payları', 'Yalnızca bedelsiz payları', 'Şirketin hiç işlem görmeyen paylarını'], 'Free float, halka açık olup yatırımcılar tarafından alınıp satılabilen payların oranıdır; likidite ve endeks ağırlığı için önemlidir.'),
  ('Bir hissede önceki gün kapanışı ile ertesi gün açılışı arasında fiyat aralığı oluşturan boşluğa teknik analizde ne denir?', 'Fiyat boşluğu (gap)', ['Çarpan (fiyat/kazanç gibi değerleme oranı)', 'Makas', 'Destek'], 'Gap, önemli bir haber ya da gece boyunca oluşan talep dengesizliği nedeniyle iki seans arasında fiyat sıçramasının bıraktığı boşluktur.'),
  ('Borsa dilinde \'defansif hisse\' ile ne kastedilir?', 'Ekonomik daralmalarda da talebi görece istikrarlı sektörlerdeki (gıda, ilaç, elektrik) hisseler', ['Savunma sanayi şirketlerinin hisseleri', 'Yalnızca bankaların hisseleri', 'Hiç temettü ödemeyen hisseler'], 'Defansif hisseler zorunlu tüketim sektörlerinde bulunduğu için dalgalı dönemlerde piyasadan daha az düşme eğilimindedir.'),
  ('Yeni çıkan bir ürünün ya da trendin hisse fiyatlarını yukarı çektiği, ancak temelden yoksun hızlı yükselişlerin görüldüğü kısa dönemlere ne ad verilir?', 'Spekülatif köpük (mini balon)', ['Bedelsiz dönemi (iç kaynaklardan pay dağıtılan dönem)', 'Tasfiye dönemi', 'Yeniden dengeleme'], 'Temel verilerle açıklanamayan hızlı yükselişler spekülatif baloncuklar olarak değerlendirilir ve sonrasında sert düzeltme görülebilir.'),
  ('Bir strateji geçmiş verilere aşırı uyarlanarak çok iyi sonuç verirken gerçek piyasada başarısız oluyorsa hangi hata yapılmıştır?', 'Aşırı uyumlama (overfitting)', ['Çeşitlendirme (riski farklı varlıklara dağıtma stratejisi)', 'Çıpalama', 'Likidite tahsisi'], 'Overfitting\'de model verideki gürültüyü de öğrenir ve yeni verilerde genelleme yapamaz.'),
  ('Fon performanslarını incelerken yalnızca hayatta kalan fonlara bakmanın yarattığı yanlılığa ne ad verilir?', 'Hayatta kalma yanlılığı', ['Çıpalama yanlılığı', 'Erişilebilirlik yanlılığı', 'Sahiplik etkisi'], 'Başarısız fonlar kapatılıp veri tabanından çıkarsa geriye kalanların ortalama getirisi olduğundan yüksek görünür.'),
  ('Bir şirketin çevre dostu görünmek için kamuoyuna abartılı ya da yanıltıcı sürdürülebilirlik iddiaları sunmasına ne ad verilir?', 'Yeşil badana (greenwashing)', ['Yeşil tahvil (iklim projelerini finanse eden borçlanma aracı)', 'Temettü verimi', 'Karbon takası'], 'Greenwashing\'de şirket gerçek çevresel performansını olduğundan iyi göstererek yatırımcı ve tüketiciyi yanıltır.'),
  ('Yatırımcıların, tütün ve silah gibi belirli sektörleri portföy dışı bırakmasına ne ad verilir?', 'Negatif eleme', ['Etkin sınır', 'Arbitraj', 'Yeniden dengeleme'], 'Negatif eleme, etik ya da sürdürülebilirlik ölçütlerine uymayan şirketlerin yatırım evreninden çıkarılmasıdır.'),
  ('Warren Buffett\'ın yatırım yaklaşımının temel dayanaklarından biri olan \'ekonomik hendek\' (moat) kavramı neyi ifade eder?', 'Şirketi rakiplerinden koruyan sürdürülebilir rekabet avantajını', ['Şirketin borç düzeyini', 'Şirketin vergi muafiyetini', 'Yöneticilerin ücret düzeyini'], 'Güçlü marka, maliyet üstünlüğü ya da ağ etkisi gibi unsurlar şirketin uzun vadeli kârını rakiplere karşı korur ve hendek olarak adlandırılır.'),
  ('Benjamin Graham\'ın \'güvenlik marjı\' ilkesi neyi öngörür?', 'Hisseyi adil değerinin belirgin biçimde altında bir fiyattan almayı', ['Hisse fiyatının sürekli yükseleceğini varsaymayı', 'Yalnızca borçla yatırım yapmayı', 'Hisseleri sadece haberlere göre satmayı'], 'Güvenlik marjı, değerleme hatalarına ve şanssızlıklara karşı tampon sağlamak için adil değerin altında satın almayı ifade eder.'),
  ('Graham\'ın \'Bay Piyasa\' benzetmesinde piyasa nasıl tasvir edilir?', 'Her gün farklı bir ruh haliyle sürekli alım ya da satım teklif eden bir ortak', ['Her zaman mantıklı davranan bir yönetici', 'Sürekli sabit fiyat veren bir banka', 'Hiç teklif vermeyen bir kurum'], 'Yatırımcı Bay Piyasa\'nın coşku ya da karamsarlığından yararlanabilir; onun duygusal tekliflerine uymak zorunda değildir.'),
  ('Benjamin Graham ve David Dodd\'un 1934\'te yayımladığı ve değer yatırımının temel metni sayılan kitap hangisidir?', 'Menkul Kıymet Analizi (Security Analysis)', ['Sıradan Hisselerde Olağanüstü Kârlar (büyüme yatırımının klasiği)', 'Akıllı Yatırımcı', 'Wall Street\'te Rastgele Yürüyüş'], 'Security Analysis, hisse ve tahvilleri temel analizle değerlemeyi ayrıntılı biçimde ortaya koyan, Columbia\'da ders veren iki akademisyenin eseridir.'),
  ('Fidelity Magellan Fonu\'nu 1977-1990 arasında yöneterek olağanüstü getirisiyle ünlenen ve \'bildiğin şeye yatırım yap\' görüşünü savunan yatırımcı kimdir?', 'Peter Lynch', ['John Templeton', 'Jesse Livermore', 'Ray Dalio'], 'Lynch, günlük yaşamda tanıdığı ürün ve şirketlerden fikir bulmayı savunmuş; PEG oranını da popülerleştirmiştir.'),
  ('Philip Fisher\'ın \'Sıradan Hisselerde Olağanüstü Kârlar\' kitabında savunduğu yaklaşım hangisidir?', 'Güçlü büyüme potansiyeli olan kaliteli şirketleri uzun süre elde tutmak', ['Hisseleri günlük alıp satmak', 'Yalnızca temettü getirisine bakmak', 'Kaldıraçlı spekülasyon yapmak'], 'Fisher\'ın büyüme yatırımcılığı, yönetim kalitesi ve araştırma yoluyla bulunan şirketleri uzun vadeli tutmaya dayanır.'),
  ('İstanbul\'da 1866\'da kurulan ve Osmanlı\'nın ilk borsası sayılan kurum hangisidir?', 'Dersaadet Tahvilat Borsası', ['İstanbul Menkul Kıymetler Borsası', 'Osmanlı Bankası', 'Düyun-u Umumiye'], 'Dersaadet Tahvilat Borsası, Galata\'da kuruldu ve Osmanlı\'da tahvil ve hisse işlemlerinin düzenlendiği ilk borsa kabul edilir.'),
  ('Sermaye Piyasası Kurulu\'nun temelini oluşturan Sermaye Piyasası Kanunu Türkiye\'de hangi yıl çıkarılmıştır?', '1981', ['1929', '1994', '2005'], '1981 tarihli Sermaye Piyasası Kanunu SPK\'yı ve modern sermaye piyasası düzenlemesini başlatmış, 1980\'lerdeki liberalleşmeyle borsa kurulmuştur.'),
  ('Bir yatırımın değeri 5 yılda 100 TL\'den 200 TL\'ye çıkmıştır. Yıllık bileşik büyüme oranı (CAGR) yaklaşık yüzde kaçtır?', '14,9', ['20', '40', '10'], 'CAGR = 2^(1/5) − 1 ≈ 0,1487, yani yüzde 14,9; basit bölme 100/5 = yüzde 20 olurdu ama bileşik etkiyi dikkate almaz.'),
  ('Üç ayda yüzde 4 getiri sağlayan bir yatırım aynı hızla yıl boyunca devam ederse yıllık bileşik getiri yaklaşık yüzde kaçtır?', '17', ['16,0', '4', '12'], '(1,04)^4 − 1 ≈ 0,1699, yani yaklaşık yüzde 17; basit çarpma 4×4 = 16 verir ama bileşik etkiyi kaçırır.'),
  ('Bir hisseden 100 adedi 10 TL\'den, 100 adedi 20 TL\'den alınmıştır. Güncel fiyat 12 TL ise toplam zarar ya da kâr yüzde kaçtır?', 'Yüzde 20 zarar', ['Yüzde 20 kâr', 'Yüzde 16,7 kâr', 'Yüzde 40 zarar'], 'Ortalama maliyet 15 TL; fiyat 12 TL olduğundan (12 − 15) / 15 = −yüzde 20.'),
  ('Bir fon birinci yıl yüzde 20 kazanıp ikinci yıl yüzde 10 kaybetmiştir. İki yıllık toplam getirisi yüzde kaçtır?', '8', ['10', '30', '5'], '1,20 × 0,90 = 1,08, yani toplam yüzde 8; yıllık getirileri toplamak (20 − 10 = 10) bileşik etkiyi yok sayar.'),
  ('Yatırımcının tahvil portföyünü farklı vadelere eşit dağıtarak her vade geldiğinde yeniden yatırdığı stratejiye ne ad verilir?', 'Merdiven (ladder) stratejisi', ['Barbell stratejisi', 'Bullet stratejisi', 'Kaldıraç stratejisi'], 'Merdiven stratejisinde vadeler kademeli dağıtıldığı için faiz riski ve yeniden yatırım riski zamana yayılır.'),
  ('ABD Hazinesi\'nin 1997\'de ihraç etmeye başladığı, anaparası enflasyona göre ayarlanan tahvillere ne ad verilir?', 'TIPS', ['Eurobond', 'Konsol', 'Kira sertifikası'], 'Enflasyona Endeksli Hazine Menkul Kıymetleri (TIPS), anaparası tüketici fiyat endeksine göre artırıldığı için enflasyona karşı koruma sağlar.'),
  ('Vadesi uzun olan bir tahvilin faiz değişimine karşı fiyat duyarlılığı kısa vadeliye göre neden yüksektir?', 'Nakit akışlarının daha geç ve uzun süre iskonto edilmesi nedeniyle', ['Kuponun her zaman çok yüksek olması nedeniyle', 'Devletin garantisi nedeniyle', 'Vergi oranı farkı nedeniyle'], 'Uzak vadeli nakit akışlarının bugünkü değeri iskonto oranındaki değişikliğe daha duyarlıdır; bu yüzden süre uzadıkça faiz riski artar.'),
  ('Piyasa faizleri düşerken uzun vadeli sabit kuponlu tahvile sahip yatırımcının durumu nasıldır?', 'Tahvil fiyatı yükseldiği için sermaye kazancı elde edebilir', ['Tahvil fiyatı düşer', 'Tahvil nominal değerini yitirir', 'Kupon ödemesi durur'], 'Faizler düşünce sabit kuponlu tahvilin getirisi daha cazip kalır ve fiyatı yükselir; bu yükselişin ölçüsü tahvilin süresiyle artar.'),
  ('Devlet iç borçlanma senetleri piyasasında \'gösterge tahvil\' neyi ifade eder?', 'En çok işlem gören, piyasa faizini temsil eden belirli vadeli devlet tahvilini', ['En yüksek kuponlu tahvili', 'Yalnızca yabancı paralı tahvili', 'Hiç işlem görmeyen tahvili'], 'Gösterge tahvilin faizi, diğer borçlanma araçlarının fiyatlanmasında referans olarak izlenir.'),
  ('Borsa İstanbul\'da devlet tahvili, hazine bonosu ve özel sektör borçlanma araçlarının işlem gördüğü piyasa hangisidir?', 'Borçlanma Araçları Piyasası', ['Vadeli İşlem ve Opsiyon Piyasası', 'Değerli Madenler Piyasası', 'Pay Piyasası'], 'Borsa İstanbul\'da borçlanma senetleri Borçlanma Araçları Piyasası\'nda alınıp satılır; repo işlemleri ise ayrı bir piyasada yapılır.'),
  ('Hazine\'nin vadeleri uzatmaya çalışan bir borçlanma stratejisi izlemesi hangi riski azaltmayı amaçlar?', 'Kısa vadede borcun çevrilememesi (yeniden finansman) riskini', ['Temettü ödemelerinin her yıl azalması riskini ve hisse düşüşünü', 'Vergi riskini', 'Opsiyon riskini'], 'Vadeler uzadıkça borç her yıl daha az çevrilir; piyasa koşulları kötüleştiğinde finansman bulma baskısı azalır.'),
  ('Yatırımcı her işlemde yüzde 0,1 komisyon ödüyorsa, bir hisseyi alıp sattığında başa baş (kârsız-zararsız) olabilmesi için fiyatın yaklaşık yüzde kaç yükselmesi gerekir?', '0,2', ['0,1', '1', '0,02'], 'Alım ve satım için toplam maliyet yaklaşık yüzde 0,2\'dir; fiyatın bu kadar yükselmesi komisyonları karşılar.'),
  ('Yüksek portföy devir hızına sahip bir fon düşük devir hızlı fona göre genellikle hangi bakımdan daha dezavantajlı olabilir?', 'Daha fazla işlem maliyeti ve vergi etkisi oluşabilir', ['Hiç işlem yapmaz, bu yüzden getirisi yüksek olur ve vergi ödemez', 'Daha az çeşitlendirilmiştir', 'Temettü ödemez'], 'Sık alım satım komisyon, makas ve vergi giderlerini artırarak net getiriyi aşındırabilir.'),
  ('Yatırımcının doğrudan ödemediği ancak işlem sırasında alış-satış farkı nedeniyle katlandığı maliyete ne ad verilir?', 'Örtük maliyet', ['Komisyon', 'Vergi stopajı', 'Saklama ücreti'], 'Makas, kayma ve piyasa etkisi gibi unsurlar faturada görünmeyen örtük maliyetlerdir; sık işlem yapanlar için önemli olabilir.'),
  ('İki fon aynı brüt getiriyi sağlıyor; A fonunun yıllık gideri yüzde 0,5, B fonunun yüzde 2\'dir. Uzun vadede hangi fon daha yüksek net birikim sağlar ve neden?', 'A fonu; düşük gider yıllık bileşik etkiyle birikimi daha az aşındırır', ['B fonu; çünkü yüksek ücretli fonlar daha iyidir', 'İkisi aynı sonucu verir', 'B fonu; çünkü ücretler getiriye eklenir'], 'Yıllık ücret farkı her yıl bileşik büyümeden düşer; yıllar geçtikçe aradaki net birikim farkı büyür.'),
  ('Wall Street adı hangi tarihî nesneden gelir?', 'Hollandalı yerleşimcilerin Manhattan\'da inşa ettiği savunma duvarı', ['Bir bankanın mermer duvarı', 'Bir kilisenin duvarı', 'Bir limanın dalgakıranı'], 'New Amsterdam döneminde Hollandalılar güney Manhattan\'da bir savunma duvarı yaptı; sokağın adı buradan gelir.'),
  ('Londra Borsası\'nda 27 Ekim 1986\'da yaşanan ve elektronik işlem, komisyonların serbestleşmesi ve yabancı katılımı getiren düzenlemelere ne ad verilir?', 'Big Bang', ['Kara Pazartesi', 'Plaza', 'Brady'], 'Big Bang, Londra piyasasını elektronik ve rekabetçi hâle getiren, sabit komisyonları kaldıran büyük reformdur.'),
  ('1987 çöküşünden sonra borsalarda yaygınlaşan ve fiyatlar belirli bir oranda düştüğünde işlemleri durduran düzenleme neydi?', 'Devre kesiciler', ['Takas yasağı', 'Rüçhan düzenlemesi', 'Sabit komisyon'], 'Çöküşün otomatik satışlarla hızlanması üzerine devre kesici mekanizmalar işleme konuldu.'),
  ('Kara para aklama ve terörün finansmanıyla mücadele standartlarını belirleyen ve ülkeleri \'gri liste\' gibi listelerle değerlendiren uluslararası kuruluş hangisidir?', 'Mali Eylem Görev Gücü (FATF)', ['Uluslararası Çalışma Örgütü (çalışma standartlarını belirleyen kuruluş)', 'OPEC', 'Dünya Sağlık Örgütü'], 'FATF 1989\'da kurulmuştur; ülkelerin kara para aklamaya karşı önlemlerini değerlendirir ve eksiği olanları izleme listelerine alır.'),
  ('Dünya genelinde finansal piyasaların korku göstergesi olarak anılan VIX endeksi neyi ölçer?', 'S&P 500 opsiyonlarından türetilen yaklaşık 30 günlük beklenen oynaklığı', ['Altın fiyatını', 'Faiz farkını', 'Konut fiyatlarını'], 'VIX, S&P 500 opsiyon fiyatlarından hesaplanan piyasa beklentisini yansıtır; yüksek değerler belirsizlik ve korku artışına işaret eder.'),
  ('Kullanım fiyatı 100 TL, ödenen prim 6 TL olan bir alım opsiyonunun vade sonu başa baş hisse fiyatı kaç TL\'dir?', '106', ['106,5', '100', '6'], 'Alım opsiyonunda başa baş = kullanım fiyatı + prim = 100 + 6 = 106 TL.'),
  ('Bir yatırımcı, 50 TL kullanım fiyatlı bir satım opsiyonu için 4 TL prim ödemiştir. Vade sonunda hisse fiyatı hangi düzeyin altına inerse yatırımcı net kâr elde etmeye başlar?', '46', ['46,5', '50', '4'], 'Satım opsiyonunda başa baş = kullanım fiyatı − prim = 50 − 4 = 46 TL.'),
  ('Derecelendirme kuruluşlarına yöneltilen çıkar çatışması eleştirisinin dayanağı nedir?', 'Notu verilen ihraççının derecelendirme ücretini ödemesi', ['Notların tamamen ücretsiz olması', 'Kuruluşların devlete ait olması', 'Notların hiç yayımlanmaması'], '\'İhraççı öder\' modelinde not alan şirket derecelendiriciye ödeme yaptığı için daha yüksek not verme baskısı oluşabileceği eleştirilir; 2008 krizinde bu tartışma yoğunlaştı.'),
  ('Derecelendirme kuruluşlarının \'negatif görünüm\' ifadesi neyi bildirir?', 'Notun orta vadede düşürülme olasılığının arttığını', ['Notun artırılacağını', 'Hisse bölünmesi olacağını', 'Şirketin kapatıldığını'], 'Görünüm, notun önümüzdeki 1-2 yıl içinde hangi yöne gidebileceğine dair beklentiyi gösterir; negatif görünüm not indirimi riskini işaret eder.'),
  ('Bir yatırımcı ya da şirketin hisselerinin yüzde 50\'sinden fazlasını satın alarak yönetim kontrolünü ele geçirmesi hâlinde Türkiye\'de halka açık şirketlerde genel olarak hangi yükümlülük doğar?', 'Diğer ortaklara zorunlu pay alım teklifi yapma', ['Hisseleri bedelsiz dağıtma', 'Şirketi kapatma', 'Borsa komisyonu ödememe'], 'Yönetim kontrolünü devralan taraf, azınlık ortaklara çıkış fırsatı tanımak için belirli koşullarda pay alım teklifi yapmakla yükümlüdür.'),
  ('Aynı şirketin A ve B sınıfı hisseleri farklı sayıda oy hakkı taşıyorsa bu yapıya ne ad verilir?', 'Çift sınıflı hisse yapısı', ['Hisse bölünmesi', 'Bedelsiz artırım', 'Rüçhan düzenlemesi'], 'Çift sınıflı yapıda bir sınıf daha çok oy taşıyabilir; kurucuların kontrolü az sermayeyle koruması mümkündür.'),
  ('Fibonacci geri çekilme düzeyleri teknik analizde hangi amaçla kullanılır?', 'Bir trend içindeki olası düzeltme seviyelerini tahmin etmek için', ['Temettü hesaplamak için', 'Faiz oranını belirlemek için', 'Şirket değerini bulmak için'], 'Fibonacci oranlarına (örneğin yüzde 38,2 ve 61,8) dayalı seviyeler, trend içi geri çekilmelerde olası destek ve direnç bölgeleri olarak izlenir.'),
  ('Hacim göstergelerinde fiyat yeni zirve yaparken hacmin giderek azalması çoğu teknik analizciye neyi düşündürür?', 'Yükselişin zayıfladığını ve dönüş riskini', ['Yükselişin hızlanacağını ve talebin güçlendiğini, düşüş riski olmadığını', 'Temettünün artacağını', 'Şirketin borsadan çıkacağını'], 'Fiyat artarken katılımın azalması, yükselişin güçlü bir talep desteğine sahip olmadığına işaret eder.'),
  ('Fiyat grafiğinde birbirini izleyen iki tepe ve ikisinden daha yüksek bir orta tepeden oluşan şekle ne ad verilir?', 'Omuz-baş-omuz formasyonu', ['Çift taban formasyonu', 'Üçgen', 'Bayrak'], 'Omuz-baş-omuz, genellikle yükselişin sonunda ortaya çıkan ve trend dönüşünü haber veren bir formasyondur.'),
  ('Büyüme hissesi ile değer hissesi karşılaştırıldığında hangisi genel olarak doğrudur?', 'Değer hisselerinin F/K ve PD/DD çarpanları genelde daha düşüktür', ['Büyüme hisseleri her zaman düşük F/K taşır', 'Değer hisseleri hiç temettü ödemez', 'İkisi arasında fark yoktur'], 'Değer hisseleri piyasada ucuz fiyatlanan, büyüme hisseleri ise kâr artışı beklentisiyle yüksek çarpanla işlem gören hisseleri anlatır.'),
  ('Bir şirketin hisse fiyatı sürekli düşük görünüp çarpanlarının ucuz olmasına rağmen temel sorunları nedeniyle yükselmeyen duruma ne ad verilir?', 'Değer tuzağı', ['Altın kesişim', 'Short squeeze', 'Rüçhan fırsatı'], 'Değer tuzağında ucuzluk geçici bir fırsat değil, bozulan işin ya da kalıcı kâr düşüşünün yansımasıdır.'),
  ('Bir şirketin kârı 5 yıl boyunca yılda yüzde 20 büyüyüp sonrasında yüzde 3 büyüyeceği varsayılıyorsa bu değerleme yaklaşımı hangi adla anılır?', 'İki aşamalı büyüme modeli', ['Sabit büyüme modeli', 'Sıfır büyüme modeli', 'Konsol modeli'], 'İki aşamalı modelde yüksek büyüme dönemi ve ardından uzun vadeli sabit büyüme dönemi ayrı ayrı değerlenir.'),
  ('Bir yatırımcı yaşı ilerledikçe hisse ağırlığını azaltıp tahvil ve nakit ağırlığını artıran bir plan izliyor. Bu yaklaşıma ne ad verilir?', 'Yaşam döngüsü (glide path) stratejisi', ['Yüksek frekanslı işlem', 'Kaldıraçlı alım', 'Arbitraj'], 'Yaşam döngüsü yaklaşımında hedef tarihe yaklaşıldıkça risk azaltılır; birçok emeklilik fonu bu mantığı kullanır.'),
  ('Portföye eklenen yeni bir varlığın portföy riskini en çok azaltması için onun mevcut varlıklarla korelasyonunun nasıl olması gerekir?', 'Düşük ya da negatif', ['Çok yüksek ve pozitif', 'Tam olarak +1', 'Önemsiz'], 'Korelasyon düştükçe varlıklar farklı zamanlarda kazanç ve kayıp yaşadığından portföy dalgalanması azalır.'),
  ('Bir yatırımcı yalnızca düşük riskli bir portföy kursa da, uzun vadede hangi risk onun için önemli kalmaya devam eder?', 'Enflasyon nedeniyle reel getirinin eksiye düşme riski', ['Hisse bölünmesi riski', 'Temettü riski', 'Opsiyon riski'], 'Çok düşük getirili güvenli yatırımlar, enflasyonun altında kalırsa satın alma gücü kaybı yaşatır.'),
  ('İflas durumunda alacakların ödenme sırasında önce kıdemli borçlardan sonra ödenen ve bu nedenle daha yüksek getiri sunan tahvil türü hangisidir?', 'İkincil (sübordine) tahvil', ['Teminatlı tahvil', 'Hazine bonosu', 'Endeksli tahvil'], 'Sübordine tahvil, tasfiyede kıdemli alacaklılardan sonra gelir; bu ek risk karşılığında daha yüksek faiz sunar.'),
  ('Birçok ülkede belediyelerin altyapı projelerini finanse etmek için çıkardığı ve ABD\'de faiz geliri çoğu durumda federal vergiden muaf olan borçlanma aracına ne denir?', 'Belediye tahvili', ['Eurobond', 'Konsol', 'Ticari kâğıt'], 'ABD\'de belediye tahvillerinin faizi genellikle federal gelir vergisinden muaf olduğu için vergi oranı yüksek yatırımcılar için çekicidir.'),
  ('Altı ayda bir 40 TL kupon ödeyen bir tahvilde 180 günlük kupon döneminin 60. gününde alım yapılırsa yaklaşık birikmiş faiz kaç TL\'dir?', '13,3', ['26,7', '20', '60'], 'Birikmiş faiz = 40 × 60 / 180 ≈ 13,3 TL.'),
  ('Bir ihraççının tahvili, ipotek ya da kamu borçları havuzu gibi belirli varlıklarla güvence altına alınarak çıkarılıyorsa bu tahvil nasıl adlandırılır?', 'Teminatlı tahvil', ['İskontolu bono', 'Kuponsuz bono', 'Dönüştürülebilir bono'], 'Teminatlı tahvil, yatırımcıya ihraççı borcuna ek olarak belirli bir varlık havuzu üzerinde hak tanır; bu yüzden daha düşük getirili olabilir.'),
  ('Kredi temerrüt takasında (CDS) koruma alan taraf, koruma satana düzenli olarak ne öder?', 'Prim (spread)', ['Temettü (şirket kârından ortaklara yapılan dağıtım ödemesi)', 'Kupon', 'Anapara'], 'Koruma alan, temerrüt riskine karşı güvence karşılığında düzenli prim öder; kredi olayı olursa zararı karşı taraftan tahsil eder.'),
  ('10 milyon TL\'lik bir borç için CDS primi yıllık 300 baz puan ise koruma alanın yıllık ödeyeceği prim kaç TL\'dir?', '300.000', ['30.000', '3.000.000', '3.000'], '300 baz puan yüzde 3\'tür; 10 milyon × 0,03 = 300.000 TL.'),
  ('Birçok kredinin ya da tahvilin havuzlanıp dilimlenerek yeni menkul kıymetler yaratıldığı yapıya genel adıyla ne denir?', 'Teminatlı borç yükümlülüğü (CDO)', ['Sabit kupon bonosu (kuponu vade boyunca değişmeyen bono)', 'Konut sertifikası', 'Rüçhan senedi'], 'CDO\'lar farklı risk düzeylerinde dilimlere ayrılır; 2008 krizinde değerlemelerinin aşırı iyimser olması kayıpları büyüttü.'),
  ('Hisse senetleri ile karşılaştırıldığında tahvil piyasasının büyük bölümünün hangi türde işlem gördüğü söylenebilir?', 'Tezgâh üstü (OTC) piyasalarda', ['Yalnızca organize borsada', 'Yalnızca kapalı artırmada', 'Sadece posta yoluyla'], 'Tahvillerin çoğu bankalar ve kurumlar arasında bire bir pazarlıkla tezgâh üstünde işlem görür; hisse işlemleri ise ağırlıkla borsada yapılır.'),
  ('Emir güdümlü piyasada fiyat nasıl oluşur?', 'Alıcıların ve satıcıların emirlerinin emir defterinde eşleşmesiyle', ['Piyasa yapıcının tek başına fiyat belirlemesiyle', 'Devletin fiyat açıklamasıyla', 'Rastgele'], 'Emir güdümlü piyasada fiyat emir defterindeki talep ve arzın eşleşmesiyle belirlenir; fiyat güdümlü piyasada ise piyasa yapıcı kotasyon verir.'),
  ('Faiz getirisi yerine kâr payı esasıyla çalışan, faize duyarlılığı olanlara hitap eden fon türü hangisidir?', 'Katılım fonu', ['Hisse yoğun fon', 'Serbest fon', 'Eurobond borçlanma fonu'], 'Katılım fonları, faiz içeren araçlar yerine kira sertifikası ve katılım hesabı gibi uygun varlıklara yatırım yapar.'),
  ('Fon yöneticisi hisse piyasası düşerken portföyün yarısını nakde çevirerek düşüş riskini azaltmaya çalışıyor. Bu hamlenin olası bedeli nedir?', 'Piyasa toparlanırsa yükselişi kaçırma riski', ['Temettü artışı', 'Vergi iadesi', 'Daha düşük makas'], 'Zamanlama stratejisi, hareketin yönünü doğru tahmin etmeyi gerektirir; yanlış zamanlamada kazanç kaçırılır.'),
  ('Hisse senedi fiyatı belirli bir seviyeye ulaşınca otomatik satış emri veren \'kâr al\' emrine ne ad verilir?', 'Hedef fiyat (take-profit) emri', ['Zarar durdur emri', 'Piyasa emri', 'Gün emri'], 'Take-profit emri, istenen kâra ulaşıldığında pozisyonu otomatik kapatarak kazancı güvene alır.'),
  ('Bir şirketin hisselerinin bir günde birkaç kez tavan fiyatta kapanması, alıcı ve satıcı arasında genelde hangi dengesizliği gösterir?', 'Alıcı tarafında talep fazlası olduğunu', ['Satıcı tarafında yoğun arz olduğunu', 'Piyasanın kapandığını', 'Takas gecikmesini'], 'Tavan fiyatta kapanış, o fiyattan alım isteyenlerin satılmak istenen paydan fazla olduğunu gösterir; talep gerçekleşmeyen emirler kuyrukta bekler.'),
  ('Bir yatırımcı, F/K oranı 8 olan bir hisseyi sektör ortalaması olan 15\'e göre ucuz buluyor; oysa şirketin geçen yılki kârının önemli bölümü bir defalık gayrimenkul satışından geliyor. Yatırımcı ne yapmalıdır?', 'Olağan dışı geliri ayıklayarak normalleştirilmiş kâr üzerinden F/K\'yı yeniden hesaplamalıdır', ['Şirketin hisselerini hemen almalıdır', 'Kâr bilgisini yok saymalıdır', 'Sektör ortalamasını yok saymalıdır'], 'Tek seferlik gelir kârı şişirdiği için F/K olduğundan düşük görünür; sürdürülebilir kâr üzerinden hesap daha sağlıklı karşılaştırma sağlar.'),
  ('A şirketinin F/K\'sı 20 ve beklenen kâr büyümesi yüzde 10; B şirketinin F/K\'sı 30 ve beklenen kâr büyümesi yüzde 30\'dur. PEG oranına göre hangisi daha ucuz görünür?', 'B (PEG 1,0)', ['A (PEG 2,0)', 'İkisi eşit', 'Hesaplanamaz'], 'A\'nın PEG\'i 20/10 = 2, B\'nin PEG\'i 30/30 = 1\'dir; büyüme hesaba katılınca B daha ucuz görünür.'),
  ('Net kârı 100 milyon TL ve 50 milyon payı olan bir şirket, kârı değişmeden 10 milyon yeni pay çıkarıyor. Hisse başına kâr yaklaşık kaç TL olur?', '1,67', ['1,60', '2,5', '1,2'], 'Başlangıç EPS = 100 / 50 = 2 TL; yeni pay sayısı 60 milyon olunca EPS = 100 / 60 ≈ 1,67 TL; buna sulanma (dilution) denir.'),
  ('Bir yatırımcı 80 TL\'ye aldığı hissenin 4 TL temettü verdiğini biliyor. Şirket hisseyi 2\'ye 1 bölerse temettü verimi nasıl değişir?', 'Değişmez, yüzde 5 kalır', ['Yarıya iner, çünkü fiyat bölünmeden sonra düşer', 'İki katına çıkar', 'Sıfırlanır'], 'Bölünmeden sonra fiyat 40 TL, hisse başı temettü 2 TL olur; 2/40 = yüzde 5, yani verim değişmez.'),
  ('Bir halka arzda 5.000 lot talepte bulunan bir yatırımcıya yüzde 20 oranında dağıtım yapılıyor ve fiyat 10 TL ise yatırımcının ödeyeceği tutar kaç TL\'dir?', '10.000', ['10.500', '1.000', '20.000'], 'Dağıtılan pay = 5.000 × 0,20 = 1.000 lot; ödeme = 1.000 × 10 = 10.000 TL; kalan talep tutarı iade edilir.'),
  ('Portföyün yüzde 60\'ı betası 1,2 olan hissede, yüzde 40\'ı nakittedir (beta 0). Piyasa yüzde 10 düşerse portföyün yaklaşık kaç düşmesi beklenir?', 'Yüzde 7,2', ['Yüzde 12,0', 'Yüzde 6', 'Yüzde 10'], 'Portföy betası = 0,6 × 1,2 = 0,72; beklenen düşüş = 0,72 × 10 = yüzde 7,2.'),
  ('50 TL\'den açığa satılan bir hisse 80 TL\'ye çıkarsa hisse başına zarar kaç TL\'dir ve teorik azami zarar nedir?', '30 TL; teorik olarak sınırsız', ['30 TL; en fazla 50 TL', '50 TL; en fazla 30 TL', '80 TL; sıfırla sınırlı'], 'Açığa satıcı 50 TL\'ye satıp 80 TL\'ye geri alırsa 30 TL kaybeder; fiyat için üst sınır olmadığından zarar kuramsal olarak sınırsızdır.'),
  ('50 TL\'den açığa satılan bir hisse 40 TL\'ye inerse hisse başına kâr kaç TL\'dir ve kâr için üst sınır nedir?', '10 TL; en fazla 50 TL', ['10 TL; sınırsız', '40 TL; en fazla 10 TL', '50 TL; sınırsız'], '50 − 40 = 10 TL kâr; fiyat en fazla sıfıra inebileceğinden azami kazanç 50 TL ile sınırlıdır.'),
  ('Bir yatırımcı faizlerin yükseleceğini beklemektedir. Tahvil portföyünün duyarlılığını azaltmak için hangi adımı atması mantıklıdır?', 'Ortalama süreyi kısaltmak', ['Uzun vadeli sabit kuponlu tahvil almak', 'Tüm paraya kaldıraç eklemek', 'Portföyü hiç değiştirmemek'], 'Faiz artışında uzun vadeli sabit kuponlu tahviller en çok değer kaybettiğinden duyarlılığı düşürmek için süre kısaltılır.'),
  ('Enflasyon beklentisinin yükseldiği bir ortamda yatırımcı için sabit kuponlu uzun vadeli tahvil ile enflasyona endeksli tahvil karşılaştırıldığında hangisi daha uygun görünür?', 'Enflasyona endeksli tahvil, çünkü anapara ve getiri enflasyonla birlikte artar', ['Sabit kuponlu tahvil, çünkü enflasyon kuponu artırır', 'İkisi aynıdır', 'Her iki tahvil de enflasyondan etkilenmez'], 'Sabit kupon enflasyonla erirken endeksli tahvilde anapara fiyat artışına göre ayarlandığı için reel değer korunur.'),
  ('Bir şirket bedelsiz sermaye artırımı duyurduktan sonra hissenin teorik fiyatı düşüyor. Yatırımcının bu düşüşe bakışı nasıl olmalıdır?', 'Pay sayısı arttığı için fiyatın teknik olarak düşmesi gerçek zarar anlamına gelmez', ['Kesin zarar edilmiştir', 'Şirket batmıştır', 'Temettü iptal edilmiştir'], 'Bedelsiz artırımda ortak daha çok paya sahip olur, fiyat bölünmeye göre ayarlanır; toplam değer kendiliğinden değişmez.'),
  ('Aynı sektörde faaliyet gösteren iki hisse arasındaki korelasyon 0,95\'tir. Portföyüne bunlardan birini ekleyen yatırımcı hakkında hangisi doğrudur?', 'Çeşitlendirme faydası çok sınırlı kalır', ['Çeşitlendirme faydası çok yüksektir, çünkü iki farklı şirket vardır', 'Getiriyi garantiler', 'Korelasyon ilgisizdir'], 'Çok yüksek korelasyonlu varlıklar aynı yönde hareket ettiği için portföy riskini anlamlı biçimde azaltmaz.'),
  ('Bir fonun beş yıllık getirisi yüzde 80, ölçüt endeksin ise yüzde 60\'tır. Fonun betası 1,4 ise ek getiri hakkında en doğru yorum hangisidir?', 'Fazla getirinin bir bölümü daha yüksek riskten kaynaklanıyor olabilir', ['Fon kesinlikle ustalıkla yönetilmiştir', 'Ölçüt endeks yanlıştır', 'Beta ile getiri ilgisizdir'], 'Beta 1,4 olan fon piyasa yükselirken daha çok kazanır; üstün getiri risk ayarlaması yapılmadan yönetici başarısı sayılamaz.'),
  ('Opsiyon yazmayan bir yatırımcı 10 sözleşme alım opsiyonu satın alıyor; her sözleşme 100 hisse için olup birim prim 3 TL\'dir. En çok kaç TL kaybedebilir?', '3.000', ['30.000', '300', 'Sınırsız'], 'Maliyet = 10 sözleşme × 100 hisse × 3 TL = 3.000 TL; opsiyon alıcısının azami kaybı ödediği primle sınırlıdır.'),
  ('Bir yatırımcı kripto cüzdanında dolara endeksli sabit koin tutuyor. Bu varlık için aşağıdaki risklerden hangisi, \'sabit\' ifadesine rağmen ortaya çıkabilir?', 'Teminat veya algoritmanın çökmesi sonucu dolar paritesinin kaybedilmesi', ['Dolar basılması', 'Hisse bölünmesi', 'Rüçhan hakkı'], 'Sabit koinler değerlerini teminat ya da algoritma ile korur; güven kaybı ya da teminat sorunu varsa pariteden sapma yaşanabilir.'),
  ('Aracı kurum, kredili işlemde yatırımcının teminatı yeterli seviyenin altına inince hisseleri zorla satabilir. Bu zorunlu satış çoğunlukla hangi mekanizmayla fiyatları daha da düşürür?', 'Ardışık zorunlu satışların satış baskısını artırması', ['Temettü ödemesinin artması', 'Rüçhan hakkının sona ermesi', 'Hisse bölünmesinin kaldırılması'], 'Fiyat düştükçe yeni teminat çağrıları ve zorunlu satışlar tetiklenir; bu satışlar fiyatı daha aşağı çeker.'),
  ('Halka açık anonim şirketlerde yönetim kuruluna belirli bir tavana kadar sermaye artırım yetkisi veren sisteme Türkiye\'de ne ad verilir?', 'Kayıtlı sermaye sistemi', ['Bedelsiz sistem', 'Rüçhan sistemi', 'Pay geri alım sistemi'], 'Kayıtlı sermaye sisteminde yönetim kurulu, genel kurul onayıyla belirlenen kayıtlı sermaye tavanına kadar yeni pay çıkarma yetkisi kazanır.'),
  ('Bir aracı kurumun iflası hâlinde yatırımcıların belirli bir tutara kadar alacağını güvence altına alan Türkiye\'deki kuruluş hangisidir?', 'Yatırımcı Tazmin Merkezi', ['Tasarruf Mevduatı Sigorta Fonu', 'Hazine ve Maliye Bakanlığı', 'Kredi Kayıt Bürosu'], 'Yatırımcı Tazmin Merkezi, aracı kurumların yükümlülüklerini yerine getirememesi durumunda yatırımcıların belirlenen limite kadar zararını tazmin eder.'),
  ('Takas işlemlerinde merkezi karşı taraf (CCP) uygulamasının amacı nedir?', 'Alıcı ile satıcı arasına girerek her iki tarafa karşı taraf riskinden kaçınma imkânı vermek', ['İşlem komisyonunu artırmak', 'Hisse fiyatını sabitlemek', 'Temettü ödemesini hızlandırmak'], 'CCP, her işlemde alıcının satıcısı ve satıcının alıcısı konumuna geçer; bir tarafın temerrüdü diğerini doğrudan etkilemez.'),
  ('Bir şirketin 800 milyon TL piyasa değeri vardır. Yeni pay çıkarıp 200 milyon TL nakit toplarsa, başka etki yoksa piyasa değeri teorik olarak kaç milyon TL olur?', '1.000', ['1.000,5', '600', '1.200'], 'Şirketin değeri toplanan nakit kadar artar: 800 + 200 = 1.000 milyon TL; yeni payla pay sayısı da artacağından hisse başına değer aynı kalır.'),
  ('Rüçhan hakkı kuponu (rüçhan kuponu) borsada alınıp satılabiliyorsa rüçhan hakkını kullanmak istemeyen ortak ne yapabilir?', 'Hakkı kuponu satarak değerini nakde çevirebilir', ['Kuponu iptal ettirip şirketten bedelini geri isteyebilir', 'Hisseyi şirkete bedava devredebilir', 'Hakkı hiç kullanamaz'], 'Rüçhan hakkı kullanılmayacaksa satılarak sulanmanın etkisi kısmen telafi edilebilir.'),
  ('Yatırım fonlarında satış sırasında alınan \'çıkış komisyonu\'nun amacı çoğunlukla nedir?', 'Kısa vadeli girip çıkan yatırımcıyı caydırıp kalıcı yatırımcıyı ödüllendirmek', ['Fonun vergisini ödemek', 'Hisse fiyatını sabitlemek', 'Temettü dağıtmak'], 'Çıkış komisyonu özellikle erken çıkışlarda yüksek tutularak fon yönetimini kısa vadeli giriş çıkışlardan korur.'),
  ('Bir yatırımcı iki yıl önce 100 TL\'ye aldığı fonun değerinin 121 TL\'ye çıktığını görüyor. Yıllık bileşik getiri yüzde kaçtır?', '10', ['21', '10,5', '15'], '(121 / 100)^(1/2) − 1 = 1,10 − 1, yani yıllık yüzde 10; iki yılın toplamı olan yüzde 21 bölünürse yaklaşık değer yüzde 10,5 çıkar ama doğru değildir.'),
  ('Fon varlıklarının yüzde 5\'inin tek bir ihraççıya yatırılabileceği gibi sınırlamalar yatırım fonu mevzuatında neden bulunur?', 'Fon portföyünde yoğunlaşma riskini sınırlayıp yatırımcıyı korumak için', ['Fon vergisini azaltmak için', 'Fon getirisini sabitlemek için', 'Fon sayısını artırmak için'], 'Tek bir varlığa aşırı yoğunlaşma, o varlığın kötü gelişmesinde tüm fon yatırımcılarını etkiler; sınırlamalar bu riski azaltır.'),
  ('Bir hisse senedinde işlem sırasının geçici olarak durdurulması (işlem durdurma) en sık hangi gerekçeyle yapılır?', 'Önemli bir bilgi duyurulurken yatırımcıların eşit bilgilenmesini sağlamak', ['Hisse fiyatını sabitlemek', 'Temettüyü artırmak', 'Şirket borçlarını silmek'], 'Önemli bir gelişme duyurulmadan işlem sürerse bilgi asimetrisi doğabilir; durdurma, bilginin eşit biçimde yayılmasını sağlar.'),
  ('Piyasa değeri ağırlıklı bir endekste bir şirketin endeksteki ağırlığı hangi büyüklüğe göre belirlenir?', 'Şirketin (serbest dolaşımdaki) piyasa değerinin toplam endeks değerine oranına', ['Hisse fiyatının en yüksek olmasına', 'Şirketin çalışan sayısına', 'Şirketin kuruluş yılına'], 'Serbest dolaşıma göre ayarlanmış piyasa değeri büyük olan şirketler endekste daha fazla ağırlığa sahip olur.'),
];
